  1→#!/usr/bin/env dotnet
  2→
  3→#:sdk Microsoft.NET.Sdk
  4→
  5→#:property TargetFramework=net10.0
  6→#:property LangVersion=latest
  7→#:property Nullable=enable
  8→#:property ImplicitUsings=enable
  9→#:property PublishAot=false
 10→
 11→using System.Diagnostics;
 12→using System.Runtime.InteropServices;
 13→using System.Security.Cryptography;
 14→using System.Text.Json;
 15→
 16→const string LibraryName = "Six.Automerge.FFI";
 17→const string NativeCrateName = "six_automerge";
 18→
 19→var options = BuildOptions.Parse(args);
 20→var projectDir = ResolveProjectDirectory(options.Project);
 21→if (!Directory.Exists(projectDir))
 22→{
 23→    Console.Error.WriteLine($"Project directory not found: {projectDir}");
 24→    return 1;
 25→}
 26→
 27→var nativeDir = Path.Combine(projectDir, "native");
 28→var codegenDir = Path.Combine(projectDir, "codegen");
 29→var generatedDir = Path.Combine(projectDir, "generated");
 30→
 31→var targetSuffix = DetectTargetSuffix();
 32→var buildProfile = "release";
 33→
 34→if (!options.Configuration.Equals("Release", StringComparison.OrdinalIgnoreCase))
 35→{
 36→    Console.WriteLine($"Requested configuration '{options.Configuration}' overridden; forcing release build for native artifacts.");
 37→}
 38→
 39→var nativeTargetDir = Path.Combine(nativeDir, $"target-{targetSuffix}");
 40→var codegenTargetDir = Path.Combine(codegenDir, $"target-{targetSuffix}");
 41→var nativeCargo = Path.Combine(nativeDir, "Cargo.toml");
 42→var codegenCargo = Path.Combine(codegenDir, "Cargo.toml");
 43→var generatedFile = Path.Combine(generatedDir, "Interop.g.cs");
 44→var nativeLibPath = Path.Combine(nativeTargetDir, buildProfile, GetCargoOutputName(targetSuffix));
 45→var buildInfoPath = Path.Combine(projectDir, "build-info.json");
 46→
 47→Console.WriteLine($"=== Building {LibraryName} ({targetSuffix}, {buildProfile}) ===");
 48→
 49→EnsureDirectoryExists(nativeTargetDir);
 50→EnsureDirectoryExists(codegenTargetDir);
 51→
 52→var buildInfo = BuildInfoStorage.Load(buildInfoPath);
 53→var currentChecksums = ChecksumCollector.Collect(projectDir);
 54→
 55→var nativeChanged = ChecksumCollector.HasDifferences(buildInfo.Checksums, currentChecksums, "native/");
 56→var codegenChanged = ChecksumCollector.HasDifferences(buildInfo.Checksums, currentChecksums, "codegen/");
 57→var platformChanged = !string.Equals(buildInfo.TargetSuffix, targetSuffix, StringComparison.OrdinalIgnoreCase);
 58→var profileChanged = !string.Equals(buildInfo.Profile, buildProfile, StringComparison.OrdinalIgnoreCase);
 59→
 60→var needsNativeBuild = options.Force || nativeChanged || platformChanged || profileChanged || !File.Exists(nativeLibPath);
 61→var needsCodegen = options.Force || codegenChanged || needsNativeBuild || !File.Exists(generatedFile);
 62→
 63→if (needsNativeBuild)
 64→{
 65→    Console.WriteLine("-> Compiling native library with cargo.");
 66→    var buildArgs = $"build --release --manifest-path \"{nativeCargo}\" --target-dir \"{nativeTargetDir}\"";
 67→
 68→    var result = RunProcess("cargo", buildArgs, nativeDir, options.Verbose);
 69→
 70→    if (result != 0)
 71→    {
 72→        Console.Error.WriteLine("Failed to build native library.");
 73→        return result;
 74→    }
 75→
 76→    if (!File.Exists(nativeLibPath))
 77→    {
 78→        Console.Error.WriteLine($"Expected native artifact not found: {nativeLibPath}");
 79→        return 1;
 80→    }
 81→}
 82→else
 83→{
 84→    Console.WriteLine("-> Native library up-to-date, skipping rebuild.");
 85→}
 86→
 87→if (needsCodegen)
 88→{
 89→    Console.WriteLine("-> Running Interoptopus code generator.");
 90→    var runArgs = $"run --release --manifest-path \"{codegenCargo}\" --target-dir \"{codegenTargetDir}\"";
 91→    var result = RunProcess("cargo", runArgs, codegenDir, options.Verbose);
 92→    if (result != 0)
 93→    {
 94→        Console.Error.WriteLine("Code generation failed.");
 95→        return result;
 96→    }
 97→
 98→    if (!File.Exists(generatedFile))
 99→    {
100→        Console.Error.WriteLine($"Expected generated file not found: {generatedFile}");
101→        return 1;
102→    }
103→}
104→else
105→{
106→    Console.WriteLine("-> Code generation sources unchanged, skipping.");
107→}
108→
109→if (!string.IsNullOrWhiteSpace(options.OutputDirectory))
110→{
111→    CopyNativeOutputs(nativeTargetDir, buildProfile, options.OutputDirectory);
112→}
113→
114→buildInfo.TargetSuffix = targetSuffix;
115→buildInfo.Profile = buildProfile;
116→buildInfo.Checksums = currentChecksums;
117→BuildInfoStorage.Save(buildInfoPath, buildInfo);
118→
119→Console.WriteLine("Build script completed successfully.");
120→return 0;
