122→static string ResolveProjectDirectory(string? providedPath)
123→{
124→    if (!string.IsNullOrWhiteSpace(providedPath))
125→    {
126→        return Path.GetFullPath(providedPath);
127→    }
128→
129→    var cwd = Directory.GetCurrentDirectory();
130→    var probe = Path.Combine(cwd, "libs", LibraryName);
131→    if (Directory.Exists(probe))
132→    {
133→        return Path.GetFullPath(probe);
134→    }
135→
136→    probe = Path.Combine(cwd, LibraryName);
137→    if (Directory.Exists(probe))
138→    {
139→        return Path.GetFullPath(probe);
140→    }
141→
142→    return cwd;
143→}
144→
145→static string DetectTargetSuffix()
146→{
147→    if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
148→    {
149→        return "windows";
150→    }
151→
152→    if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
153→    {
154→        return "linux";
155→    }
156→
157→    if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
158→    {
159→        return "macos";
160→    }
161→
162→    return "unix";
163→}
