166→static string GetCargoOutputName(string targetSuffix)
167→{
168→    return targetSuffix switch
169→    {
170→        "windows" => $"{NativeCrateName}.dll",
171→        "macos" => $"lib{NativeCrateName}.dylib",
172→        _ => $"lib{NativeCrateName}.so"
173→    };
174→}
