237→static void CopyNativeOutputs(string nativeTargetDir, string buildProfile, string outputDirectory)
238→{
239→    var releaseDir = Path.Combine(nativeTargetDir, buildProfile);
240→    if (!Directory.Exists(releaseDir))
241→    {
242→        Console.WriteLine($"Native output directory does not exist: {releaseDir}");
243→        return;
244→    }
245→
246→    // (cargoOutputName, desiredFinalName) — cargo on Windows produces no lib prefix,
247→    // but we want libsix_automerge.dll for consistent naming across platforms.
248→    var targets = new (string CargoName, string FinalName)[]
249→    {
250→        ($"{NativeCrateName}.dll", $"lib{NativeCrateName}.dll"),
251→        ($"lib{NativeCrateName}.so", $"lib{NativeCrateName}.so"),
252→        ($"lib{NativeCrateName}.dylib", $"lib{NativeCrateName}.dylib"),
253→    };
254→
255→    EnsureDirectoryExists(outputDirectory);
256→
257→    foreach (var (cargoName, finalName) in targets)
258→    {
259→        var source = Path.Combine(releaseDir, cargoName);
260→        if (!File.Exists(source))
261→        {
262→            continue;
263→        }
264→
265→        var destination = Path.Combine(outputDirectory, finalName);
266→        File.Copy(source, destination, overwrite: true);
267→        Console.WriteLine($"Copied {cargoName} -> {destination}");
268→    }
269→}
