327→sealed class BuildInfo
328→{
329→    public string TargetSuffix { get; set; } = string.Empty;
330→    public string Profile { get; set; } = string.Empty;
331→    public Dictionary<string, string> Checksums { get; set; } = new(StringComparer.OrdinalIgnoreCase);
