334→static class BuildInfoStorage
335→{
336→    public static BuildInfo Load(string path)
337→    {
338→        if (!File.Exists(path))
339→        {
340→            return new BuildInfo();
341→        }
342→
343→        try
344→        {
345→            var json = File.ReadAllText(path);
346→            return JsonSerializer.Deserialize<BuildInfo>(json) ?? new BuildInfo();
347→        }
348→        catch
349→        {
350→            return new BuildInfo();
351→        }
352→    }
353→
354→    public static void Save(string path, BuildInfo buildInfo)
355→    {
356→        var options = new JsonSerializerOptions { WriteIndented = true };
357→        var json = JsonSerializer.Serialize(buildInfo, options);
358→        File.WriteAllText(path, json);
359→    }
360→}
