  1→#!/usr/bin/env dotnet
  2→#:sdk Microsoft.NET.Sdk
  3→#:property LangVersion 13
  4→
  5→#:package CliWrap@3.6.6
  6→#:package Spectre.Console@0.49.1
  7→
  8→using System;
  9→using System.Collections.Generic;
 10→using System.IO;
 11→using System.Linq;
 12→using System.Text;
 13→using System.Threading.Tasks;
 14→using CliWrap;
 15→using Spectre.Console;
 16→
 17→// Set working directory to solution root if we're in the build directory
 18→if (Directory.GetCurrentDirectory().EndsWith("scripts"))
 19→{
 20→    Directory.SetCurrentDirectory("..");
 21→}
 22→
 23→// Configuration
 24→var searchDirectories = new List<string>
 25→{
 26→    "libs"  // Default to libs directory
 27→};
 28→
 29→var ignoredProjects = new List<string>
 30→{
 31→    // Add project names to ignore here
 32→    // Example: "Six.Example.TestProject"
 33→};
 34→
 35→var buildConfig = args.Contains("--debug") ? "Debug" : "Release";
 36→var includeSymbols = !args.Contains("--no-symbols"); // Include symbols by default, opt-out with --no-symbols
 37→var publishMode = GetPublishMode(args);
 38→
 39→// Environment variables
 40→var localFeedUrl = Environment.GetEnvironmentVariable("NUGET_FEED_LOCAL_URL");
 41→var devFeedUrl = Environment.GetEnvironmentVariable("NUGET_FEED_DEV_URL");
 42→var devFeedUsername = Environment.GetEnvironmentVariable("NUGET_FEED_DEV_USERNAME");
 43→var devFeedPat = Environment.GetEnvironmentVariable("NUGET_FEED_DEV_PAT");
 44→var stagingFeedUrl = Environment.GetEnvironmentVariable("NUGET_FEED_STAGING_URL");
 45→var stagingFeedUsername = Environment.GetEnvironmentVariable("NUGET_FEED_STAGING_USERNAME");
 46→var stagingFeedPat = Environment.GetEnvironmentVariable("NUGET_FEED_STAGING_PAT");
 47→var productionFeedUrl = Environment.GetEnvironmentVariable("NUGET_FEED_PRODUCTION_URL");
 48→var productionFeedUsername = Environment.GetEnvironmentVariable("NUGET_FEED_PRODUCTION_USERNAME");
 49→var productionFeedPat = Environment.GetEnvironmentVariable("NUGET_FEED_PRODUCTION_PAT");
 50→
 51→AnsiConsole.Write(new FigletText("Six NuGet Packager").Color(Color.Green));
 52→AnsiConsole.WriteLine();
 53→
 54→await AnsiConsole.Status()
 55→    .Spinner(Spinner.Known.Dots)
 56→    .StartAsync("Processing NuGet packaging...", async ctx =>
 57→    {
 58→        try
 59→        {
 60→            // Validate environment based on publish mode
 61→            ValidateEnvironment();
 62→
 63→            // Discover projects
 64→            ctx.Status("Discovering projects...");
 65→            var projects = DiscoverProjects(searchDirectories, ignoredProjects);
 66→            
 67→            if (projects.Count == 0)
 68→            {
 69→                AnsiConsole.MarkupLine("[red]No projects found to package![/]");
 70→                return;
 71→            }
 72→
 73→            AnsiConsole.MarkupLine($"[green]Found {projects.Count} project(s) to package[/]");
 74→            foreach (var project in projects)
 75→            {
 76→                AnsiConsole.MarkupLine($"[dim]  • {Path.GetFileNameWithoutExtension(project)}[/]");
 77→            }
 78→            AnsiConsole.WriteLine();
 79→
 80→            // Build and pack projects in parallel
 81→            ctx.Status("Building and packing projects...");
 82→            var outputDir = GetOutputDirectory();
 83→            var packResults = await BuildAndPackProjectsAsync(projects, buildConfig, outputDir);
 84→
 85→            // Report packed projects
 86→            ReportPackedProjects(packResults);
 87→
 88→            // Publish packages to target feed
 89→            List<PublishResult> publishResults = new();
 90→            if (publishMode == PublishMode.Local)
 91→            {
 92→                ctx.Status("Copying packages to local feed...");
 93→                publishResults = await CopyPackagesToLocalFeedAsync(packResults, localFeedUrl!, outputDir);
 94→                ReportPublishedProjects(publishResults);
 95→            }
 96→            else
 97→            {
 98→                // Get remote feed configuration
 99→                var feedData = GetFeedData();
100→                
101→                ctx.Status($"Publishing packages to {publishMode.ToString().ToLower()} feed...");
102→                publishResults = await PublishPackagesAsync(packResults, publishMode, feedData.Url, feedData.Pat, outputDir);
103→                ReportPublishedProjects(publishResults);
104→            }
105→
106→            // Final summary
107→            ctx.Status("Generating summary...");
108→            DisplaySummary(packResults, publishResults, publishMode, outputDir);
109→            
110→            // Always cleanup packages directory (it's temporary)
111→            if (Directory.Exists(outputDir))
112→            {
113→                ctx.Status("Cleaning up temporary packages directory...");
114→                try
115→                {
116→                    Directory.Delete(outputDir, true);
117→                    AnsiConsole.MarkupLine("[dim]✓ Cleaned up temporary packages directory[/]");
118→                }
119→                catch (Exception ex)
120→                {
121→                    AnsiConsole.MarkupLine($"[yellow]Warning: Could not clean up packages directory: {ex.Message}[/]");
122→                }
123→            }
124→            
125→            ctx.Status("Completed!");
126→            await Task.Delay(100); // Brief pause to show completion
127→        }
128→        catch (Exception ex)
129→        {
130→            AnsiConsole.MarkupLine($"[red]Error: {ex.Message}[/]");
131→            Environment.Exit(1);
132→        }
133→    });
134→
135→// Clear any remaining status and show completion message
136→AnsiConsole.WriteLine();
137→AnsiConsole.Write(new Rule("[green]✅ NuGet Packaging Completed![/]").LeftJustified());
138→
139→// Helper Methods
140→PublishMode GetPublishMode(string[] args)
141→{
142→    if (args.Contains("--local")) return PublishMode.Local;
143→    if (args.Contains("--dev") || args.Contains("--development")) return PublishMode.Development;
144→    if (args.Contains("--staging")) return PublishMode.Staging;
145→    if (args.Contains("--prod") || args.Contains("--production")) return PublishMode.Production;
146→    return PublishMode.Local; // Default to local feed
147→}
148→
149→void ValidateEnvironment()
150→{
151→    switch (publishMode)
152→    {
153→        case PublishMode.Local:
154→            if (string.IsNullOrEmpty(localFeedUrl))
155→                throw new InvalidOperationException("NUGET_FEED_LOCAL_URL environment variable is required for local publishing");
156→            break;
157→        
158→        case PublishMode.Development:
159→            if (string.IsNullOrEmpty(devFeedUrl))
160→                throw new InvalidOperationException("NUGET_FEED_DEV_URL environment variable is required for DEVELOPMENT feed publishing");
161→            if (string.IsNullOrEmpty(devFeedUsername))
162→                throw new InvalidOperationException("NUGET_FEED_DEV_USERNAME environment variable is required for DEVELOPMENT feed publishing");
163→            if (string.IsNullOrEmpty(devFeedPat))
164→                throw new InvalidOperationException("NUGET_FEED_DEV_PAT environment variable is required for DEVELOPMENT feed publishing");
165→            break;
166→        
167→        case PublishMode.Staging:
168→          if (string.IsNullOrEmpty(stagingFeedUrl))
169→            throw new InvalidOperationException("NUGET_FEED_STAGING_URL environment variable is required for STAGING feed publishing");
170→          if (string.IsNullOrEmpty(stagingFeedUsername))
171→            throw new InvalidOperationException("NUGET_FEED_STAGING_USERNAME environment variable is required for STAGING feed publishing");
172→          if (string.IsNullOrEmpty(stagingFeedPat))
173→            throw new InvalidOperationException("NUGET_FEED_STAGING_PAT environment variable is required for STAGING feed publishing");
174→          break;
175→        
176→        case PublishMode.Production:
177→          if (string.IsNullOrEmpty(productionFeedUrl))
178→            throw new InvalidOperationException("NUGET_FEED_PRODUCTION_URL environment variable is required for PRODUCTION feed publishing");
179→          if (string.IsNullOrEmpty(productionFeedUsername))
180→            throw new InvalidOperationException("NUGET_FEED_PRODUCTION_USERNAME environment variable is required for PRODUCTION feed publishing");
181→          if (string.IsNullOrEmpty(productionFeedPat))
182→            throw new InvalidOperationException("NUGET_FEED_PRODUCTION_PAT environment variable is required for PRODUCTION feed publishing");
183→          break;
184→    }
185→}
186→
187→(string Url, string Pat) GetFeedData()
188→{
189→  switch (publishMode)
190→  {
191→    case PublishMode.Local:
192→      return (localFeedUrl ?? throw new InvalidOperationException("Local feed URL is null"), string.Empty);
193→        
194→    case PublishMode.Development:
195→      return (devFeedUrl ?? throw new InvalidOperationException("Development feed URL is null"), 
196→              devFeedPat ?? throw new InvalidOperationException("Development feed PAT is null"));
197→        
198→    case PublishMode.Staging:
199→      return (stagingFeedUrl ?? throw new InvalidOperationException("Staging feed URL is null"), 
200→              stagingFeedPat ?? throw new InvalidOperationException("Staging feed PAT is null"));
201→        
202→    case PublishMode.Production:
203→      return (productionFeedUrl ?? throw new InvalidOperationException("Production feed URL is null"), 
204→              productionFeedPat ?? throw new InvalidOperationException("Production feed PAT is null"));
205→        
206→    default:
207→      throw new InvalidOperationException($"Unknown publish mode: {publishMode}");
208→  }
209→}
