211→
212→List<string> DiscoverProjects(List<string> searchDirs, List<string> ignored)
213→{
214→    var projects = new List<string>();
215→    
216→    foreach (var dir in searchDirs)
217→    {
218→        if (!Directory.Exists(dir))
219→        {
220→            AnsiConsole.MarkupLine($"[yellow]Warning: Directory '{dir}' does not exist, skipping...[/]");
221→            continue;
222→        }
223→
224→        var foundProjects = Directory.GetFiles(dir, "*.csproj", SearchOption.AllDirectories)
225→            .Where(p => !ignored.Any(ignore => Path.GetFileNameWithoutExtension(p).Equals(ignore, StringComparison.OrdinalIgnoreCase)))
226→            .ToList();
227→
228→        projects.AddRange(foundProjects);
229→    }
230→
231→    return projects.OrderBy(p => Path.GetFileNameWithoutExtension(p)).ToList();
232→}
233→
234→string GetOutputDirectory()
235→{
