241→async Task<List<PackResult>> BuildAndPackProjectsAsync(List<string> projects, string config, string outputDir)
242→{
243→    // Ensure output directory exists
244→    Directory.CreateDirectory(outputDir);
245→
246→    var results = new List<PackResult>();
247→    
248→    // Build and pack sequentially to avoid file lock issues with dependencies
249→    foreach (var project in projects)
250→    {
251→        var projectName = Path.GetFileNameWithoutExtension(project);
252→        
253→        try
254→        {
255→            // Build with output capture
256→            var buildOutput = new StringBuilder();
257→            var buildError = new StringBuilder();
258→            
259→            var buildResult = await Cli.Wrap("dotnet")
260→                .WithArguments($"build \"{project}\" -c {config} --verbosity normal")
261→                .WithValidation(CommandResultValidation.None)
262→                .WithStandardOutputPipe(PipeTarget.ToStringBuilder(buildOutput))
263→                .WithStandardErrorPipe(PipeTarget.ToStringBuilder(buildError))
264→                .ExecuteAsync();
265→
266→            if (buildResult.ExitCode != 0)
267→            {
268→                var errorMessage = GetErrorMessage(buildError.ToString(), buildOutput.ToString(), "Build failed");
269→                results.Add(new PackResult(projectName, false, errorMessage));
270→                continue;
271→            }
272→
273→            // Pack with or without symbols based on argument
274→            var packOutput = new StringBuilder();
275→            var packError = new StringBuilder();
276→            
277→            var packArgs = includeSymbols 
278→                ? $"pack \"{project}\" -c {config} -o \"{outputDir}\" --no-build --include-symbols -p:SymbolPackageFormat=snupkg --verbosity normal"
279→                : $"pack \"{project}\" -c {config} -o \"{outputDir}\" --no-build --verbosity normal";
280→            
281→            var packResult = await Cli.Wrap("dotnet")
282→                .WithArguments(packArgs)
283→                .WithValidation(CommandResultValidation.None)
284→                .WithStandardOutputPipe(PipeTarget.ToStringBuilder(packOutput))
285→                .WithStandardErrorPipe(PipeTarget.ToStringBuilder(packError))
286→                .ExecuteAsync();
287→
288→            if (packResult.ExitCode != 0)
289→            {
290→                var errorMessage = GetErrorMessage(packError.ToString(), packOutput.ToString(), "Pack failed");
291→                results.Add(new PackResult(projectName, false, errorMessage));
292→                continue;
293→            }
294→
295→            results.Add(new PackResult(projectName, true, "Success"));
296→        }
297→        catch (Exception ex)
298→        {
299→            results.Add(new PackResult(projectName, false, ex.Message));
300→        }
301→    }
302→
303→    return results;
304→}
