307→Task<List<PublishResult>> CopyPackagesToLocalFeedAsync(List<PackResult> packResults, string localFeedPath, string outputDir)
308→{
309→    var successfulPacks = packResults.Where(r => r.Success).ToList();
310→    
311→    // Ensure local feed directory exists
312→    Directory.CreateDirectory(localFeedPath);
313→    
314→    var results = new List<PublishResult>();
315→    
316→    foreach (var pack in successfulPacks)
317→    {
318→        try
319→        {
320→            // Find .nupkg files for this project (consistent with remote publishing logic)
321→            var packageFiles = Directory.GetFiles(outputDir, $"{pack.ProjectName}*.nupkg")
322→                .Where(f => !f.EndsWith(".snupkg"))
323→                .OrderByDescending(f => File.GetLastWriteTime(f))
324→                .ToArray();
325→
326→            if (packageFiles.Length == 0)
327→            {
328→                results.Add(new PublishResult(pack.ProjectName, false, "No .nupkg files found"));
329→                continue;
330→            }
331→
332→            var latestNugetPackage = packageFiles[0];
333→            var packageBaseName = Path.GetFileNameWithoutExtension(latestNugetPackage);
334→            
335→            // Find corresponding .snupkg files
336→            var snupkgFiles = Directory.GetFiles(outputDir, $"{pack.ProjectName}*.snupkg")
337→                .Where(f => Path.GetFileNameWithoutExtension(f) == packageBaseName)
338→                .OrderByDescending(f => File.GetLastWriteTime(f))
339→                .ToArray();
340→
341→            // Copy main package file
342→            var mainFileName = Path.GetFileName(latestNugetPackage);
343→            var mainDestPath = Path.Combine(localFeedPath, mainFileName);
344→            File.Copy(latestNugetPackage, mainDestPath, true);
345→            
346→            var copiedFiles = 1;
347→            
348→            // Copy symbols package if it exists
349→            if (snupkgFiles.Length > 0)
350→            {
351→                var latestSnupkgFile = snupkgFiles[0];
352→                var symbolFileName = Path.GetFileName(latestSnupkgFile);
353→                var symbolDestPath = Path.Combine(localFeedPath, symbolFileName);
354→                File.Copy(latestSnupkgFile, symbolDestPath, true);
355→                copiedFiles++;
356→            }
357→
358→            var message = copiedFiles == 1 
359→                ? $"Copied package to {localFeedPath}" 
360→                : $"Copied package and symbols to {localFeedPath}";
361→                
362→            results.Add(new PublishResult(pack.ProjectName, true, message));
363→        }
364→        catch (Exception ex)
365→        {
366→            results.Add(new PublishResult(pack.ProjectName, false, ex.Message));
367→        }
368→    }
369→    
370→    return Task.FromResult(results);
371→}
