373→async Task<List<PublishResult>> PublishPackagesAsync(
374→  List<PackResult> packResults, 
375→  PublishMode mode, 
376→  string feedUrl, 
377→  string apiKey,
378→  string outputDir)
379→{
380→    var successfulPacks = packResults.Where(r => r.Success).ToList();
381→
382→    var tasks = successfulPacks.Select(async pack =>
383→    {
384→        try
385→        {
386→            // Find the latest .nupkg file for this project (like the PowerShell script)
387→            var packageFiles = Directory.GetFiles(outputDir, $"{pack.ProjectName}*.nupkg")
388→                .Where(f => !f.EndsWith(".snupkg"))
389→                .OrderByDescending(f => File.GetLastWriteTime(f))
390→                .ToArray();
391→
392→            if (packageFiles.Length == 0)
393→            {
394→                return new PublishResult(pack.ProjectName, false, "No package file found");
395→            }
396→
397→            var latestNugetPackage = packageFiles[0];
398→            
399→            // Find corresponding .snupkg file (like the PowerShell script)
400→            var packageBaseName = Path.GetFileNameWithoutExtension(latestNugetPackage);
401→            var snupkgFiles = Directory.GetFiles(outputDir, $"{pack.ProjectName}*.snupkg")
402→                .Where(f => Path.GetFileNameWithoutExtension(f) == packageBaseName)
403→                .OrderByDescending(f => File.GetLastWriteTime(f))
404→                .ToArray();
405→
406→            // Push main package
407→            var pushOutput = new StringBuilder();
408→            var pushError = new StringBuilder();
409→            
410→            var pushResult = await Cli.Wrap("dotnet")
411→                .WithArguments($"nuget push \"{latestNugetPackage}\" --skip-duplicate --api-key \"{apiKey}\" --source \"{feedUrl}\"")
412→                .WithValidation(CommandResultValidation.None)
413→                .WithStandardOutputPipe(PipeTarget.ToStringBuilder(pushOutput))
414→                .WithStandardErrorPipe(PipeTarget.ToStringBuilder(pushError))
415→                .ExecuteAsync();
416→
417→            if (pushResult.ExitCode != 0)
418→            {
419→                var errorMessage = GetErrorMessage(pushError.ToString(), pushOutput.ToString(), "Push failed");
420→                return new PublishResult(pack.ProjectName, false, errorMessage);
421→            }
422→
423→            // Push symbols if exists (matching the PowerShell script logic)
424→            if (snupkgFiles.Length > 0)
425→            {
426→                var latestSnupkgFile = snupkgFiles[0];
427→                var symbolPushOutput = new StringBuilder();
428→                var symbolPushError = new StringBuilder();
429→                
430→                var symbolPushResult = await Cli.Wrap("dotnet")
431→                    .WithArguments($"nuget push \"{latestSnupkgFile}\" --skip-duplicate --api-key \"{apiKey}\" --source \"{feedUrl}\"")
432→                    .WithValidation(CommandResultValidation.None)
433→                    .WithStandardOutputPipe(PipeTarget.ToStringBuilder(symbolPushOutput))
434→                    .WithStandardErrorPipe(PipeTarget.ToStringBuilder(symbolPushError))
435→                    .ExecuteAsync();
436→
437→                // Symbol push failure is not critical
438→                if (symbolPushResult.ExitCode != 0)
439→                {
440→                    return new PublishResult(pack.ProjectName, true, "Package published (symbols failed)");
441→                }
442→                
443→                return new PublishResult(pack.ProjectName, true, "Published with symbols");
444→            }
445→
446→            return new PublishResult(pack.ProjectName, true, "Published successfully");
447→        }
448→        catch (Exception ex)
449→        {
450→            return new PublishResult(pack.ProjectName, false, ex.Message);
451→        }
452→    });
453→
454→    return (await Task.WhenAll(tasks)).ToList();
455→}
