567→string GetErrorMessage(string stderr, string stdout, string defaultMessage)
568→{
569→    // Combine stderr and stdout
570→    var allOutput = $"{stderr}\n{stdout}".Trim();
571→    
572→    if (string.IsNullOrWhiteSpace(allOutput))
573→        return defaultMessage;
574→    
575→    // Look for error lines
576→    var lines = allOutput.Split('\n', StringSplitOptions.RemoveEmptyEntries);
577→    var errorLines = lines.Where(line => 
578→        line.Contains("error", StringComparison.OrdinalIgnoreCase) ||
579→        line.Contains("failed", StringComparison.OrdinalIgnoreCase) ||
580→        line.Contains("exception", StringComparison.OrdinalIgnoreCase))
581→        .Take(3) // Limit to first 3 error lines
582→        .ToArray();
583→    
584→    if (errorLines.Length > 0)
585→    {
586→        // Clean up the error messages
587→        var cleanErrors = errorLines.Select(line => 
588→            line.Trim()
589→                .Replace("error:", "", StringComparison.OrdinalIgnoreCase)
590→                .Replace("Error:", "", StringComparison.OrdinalIgnoreCase)
591→                .Trim())
592→            .Where(line => !string.IsNullOrWhiteSpace(line))
593→            .ToArray();
594→        
595→        if (cleanErrors.Length > 0)
596→        {
597→            return string.Join(" | ", cleanErrors);
598→        }
599→    }
600→    
601→    // If no specific errors found, return first few lines of output
602→    var firstLines = lines.Take(2).Where(line => !string.IsNullOrWhiteSpace(line)).ToArray();
603→    return firstLines.Length > 0 ? string.Join(" | ", firstLines) : defaultMessage;
604→}
605→
606→string TruncateMessage(string message, int maxLength)
607→{
608→    if (string.IsNullOrEmpty(message) || message.Length <= maxLength)
609→        return message;
610→    
611→    return message.Substring(0, maxLength - 3) + "...";
612→}
