  8→using System;
  9→using System.IO;
 10→using System.Threading.Tasks;
 11→using CliWrap;
 12→using CliWrap.Buffered;
 13→using Spectre.Console;
 14→
 15→// Set working directory to solution root
 16→var currentDir = Directory.GetCurrentDirectory();
 17→if (currentDir.EndsWith("scripts"))
 18→{
 19→    Directory.SetCurrentDirectory("..");
 20→}
 21→
 22→// Projects to ignore for testing
 23→List<string> ignoredProjects = [];
 24→
 25→// Run all tests in the solution
 26→await AnsiConsole.Status()
 27→    .Spinner(Spinner.Known.Dots)
 28→    .StartAsync("Running tests...", async ctx =>
 29→    {
 30→        try
 31→        {
 32→            // Find all test projects (excluding ignored ones)
 33→            var allTestProjects = Directory
 34→                .GetFiles(".", "*.Tests*.csproj", SearchOption.AllDirectories)
 35→                .Where(p => !p.Contains("bin") && !p.Contains("obj"))
 36→                .ToArray();
 37→            
 38→            var testProjects = allTestProjects
 39→                .Where(p => !ignoredProjects.Contains(Path.GetFileNameWithoutExtension(p)))
 40→                .ToArray();
 41→
 42→            if (testProjects.Length == 0)
 43→            {
 44→                AnsiConsole.MarkupLine("[red]No test projects found![/]");
 45→                return;
 46→            }
 47→
 48→            AnsiConsole.MarkupLine($"[green]Found {testProjects.Length} test project(s)[/]");
 49→            if (ignoredProjects.Count > 0)
 50→            {
 51→                AnsiConsole.MarkupLine($"[yellow]Ignored {ignoredProjects.Count} non-test project(s): {string.Join(", ", ignoredProjects)}[/]");
 52→            }
 53→            AnsiConsole.WriteLine();
 54→
 55→            var overallResults = new List<(string Project, bool Success, int Passed, int Failed, int Skipped, string Duration)>();
 56→
 57→            foreach (var project in testProjects)
 58→            {
 59→                var projectName = Path.GetFileNameWithoutExtension(project);
 60→                ctx.Status($"Running tests for [yellow]{projectName}[/]...");
 61→
 62→                AnsiConsole.MarkupLine($"[cyan]🧪 Running tests for {projectName}...[/]");
 63→
 64→                var result = await Cli.Wrap("dotnet")
 65→                    .WithArguments($"test \"{project}\" --logger \"console;verbosity=normal\" --no-restore")
 66→                    .WithValidation(CommandResultValidation.None)
 67→                    .ExecuteBufferedAsync();
 68→
 69→                // Parse detailed test results
 70→                var lines = result.StandardOutput.Split('\n', StringSplitOptions.RemoveEmptyEntries);
 71→                
 72→                // Show individual test results
 73→                var testLines = lines.Where(l => 
 74→                    l.Contains("Passed ") || 
 75→                    l.Contains("Failed ") || 
 76→                    l.Contains("Skipped ")).ToArray();
 77→
 78→                foreach (var testLine in testLines)
 79→                {
 80→                    if (testLine.Contains("Passed "))
 81→                    {
 82→                        var testName = ExtractTestName(testLine);
 83→                        AnsiConsole.MarkupLine($"  [green]✓[/] {testName}");
 84→                    }
 85→                    else if (testLine.Contains("Failed "))
 86→                    {
 87→                        var testName = ExtractTestName(testLine);
 88→                        AnsiConsole.MarkupLine($"  [red]✗[/] {testName}");
 89→                    }
 90→                    else if (testLine.Contains("Skipped "))
 91→                    {
 92→                        var testName = ExtractTestName(testLine);
 93→                        AnsiConsole.MarkupLine($"  [yellow]⊘[/] {testName}");
 94→                    }
 95→                }
 96→
 97→                // Parse summary - count the actual test results we displayed
 98→                var passed = testLines.Count(l => l.Contains("Passed "));
 99→                var failed = testLines.Count(l => l.Contains("Failed "));
100→                var skipped = testLines.Count(l => l.Contains("Skipped "));
101→                
102→                // Try to extract duration from the output
103→                var durationLine = lines.FirstOrDefault(l => l.Contains("Duration:") || l.Contains("Total time:") || l.Contains("Test run for"));
104→                var duration = "N/A";
105→                
106→                if (durationLine != null)
107→                {
108→                    var durationMatch = System.Text.RegularExpressions.Regex.Match(durationLine, @"(\d+(?:\.\d+)?\s*[a-z]+)");
109→                    if (durationMatch.Success)
110→                    {
111→                        duration = durationMatch.Groups[1].Value.Trim();
112→                    }
113→                }
114→                
115→                // Fallback: look for summary line patterns
116→                var summaryLine = lines.FirstOrDefault(l => 
117→                    (l.Contains("Passed!") || l.Contains("Failed!") || l.Contains("Total tests:")) &&
118→                    (l.Contains("Passed:") || l.Contains("Failed:") || l.Contains("Skipped:")));
119→                
120→                if (summaryLine != null)
121→                {
122→                    var passedMatch = System.Text.RegularExpressions.Regex.Match(summaryLine, @"Passed:\s*(\d+)");
123→                    var failedMatch = System.Text.RegularExpressions.Regex.Match(summaryLine, @"Failed:\s*(\d+)");
124→                    var skippedMatch = System.Text.RegularExpressions.Regex.Match(summaryLine, @"Skipped:\s*(\d+)");
125→                    var durationMatch = System.Text.RegularExpressions.Regex.Match(summaryLine, @"Duration:\s*([^,\]]+)");
126→
127→                    if (passedMatch.Success && int.TryParse(passedMatch.Groups[1].Value, out var summaryPassed) && summaryPassed > passed)
128→                        passed = summaryPassed;
129→                    if (failedMatch.Success && int.TryParse(failedMatch.Groups[1].Value, out var summaryFailed) && summaryFailed > failed)
130→                        failed = summaryFailed;
131→                    if (skippedMatch.Success && int.TryParse(skippedMatch.Groups[1].Value, out var summarySkipped) && summarySkipped > skipped)
132→                        skipped = summarySkipped;
133→                    if (durationMatch.Success) 
134→                        duration = durationMatch.Groups[1].Value.Trim();
135→                }
136→
137→                overallResults.Add((projectName, result.ExitCode == 0, passed, failed, skipped, duration));
138→                
139→                var statusColor = result.ExitCode == 0 ? "green" : "red";
140→                var statusIcon = result.ExitCode == 0 ? "✓" : "✗";
141→                var total = passed + failed + skipped;
142→                
143→                AnsiConsole.MarkupLine($"[{statusColor}]{statusIcon} {projectName}: {total} tests ({passed} passed, {failed} failed, {skipped} skipped) in {duration}[/]");
144→                AnsiConsole.WriteLine();
145→            }
146→
147→            // Display summary table
148→            var table = new Table()
149→                .Border(TableBorder.Rounded)
150→                .AddColumn("Project")
151→                .AddColumn("Status")
152→                .AddColumn("Passed")
153→                .AddColumn("Failed") 
154→                .AddColumn("Skipped")
155→                .AddColumn("Total")
156→                .AddColumn("Duration");
157→
158→            foreach (var (project, success, passed, failed, skipped, duration) in overallResults)
159→            {
160→                var status = success ? "[green]✓ Passed[/]" : "[red]✗ Failed[/]";
161→                var total = passed + failed + skipped;
162→                
163→                table.AddRow(
164→                    $"[cyan]{project}[/]",
165→                    status,
166→                    passed.ToString(),
167→                    failed > 0 ? $"[red]{failed}[/]" : failed.ToString(),
168→                    skipped > 0 ? $"[yellow]{skipped}[/]" : skipped.ToString(),
169→                    total.ToString(),
170→                    duration
171→                );
172→            }
173→
174→            AnsiConsole.Write(table);
175→        }
176→        catch (Exception ex)
177→        {
178→            AnsiConsole.MarkupLine($"[red]Error: {ex.Message}[/]");
179→            Environment.Exit(1);
180→        }
181→    });
182→
183→AnsiConsole.MarkupLine("[green]Test run completed![/]");
