186→// Helper function to extract test name from dotnet test output
187→string ExtractTestName(string testLine)
188→{
189→    // Test lines typically look like:
190→    // "  Passed TokenCache_GetAsync_WithValidToken_ReturnsToken [2 ms]"
191→    // "  Failed TokenProvider_GetTokenAsync_WhenTokenExpires_RequestsNewToken [< 1 ms]"
192→    
193→    var parts = testLine.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
194→    if (parts.Length >= 2)
195→    {
196→        // Skip the status word (Passed/Failed/Skipped) and take the test name
197→        var testName = parts[1];
198→        
199→        // Remove any timing information in brackets
200→        var bracketIndex = testName.IndexOf('[');
201→        if (bracketIndex > 0)
202→        {
203→            testName = testName.Substring(0, bracketIndex).Trim();
204→        }
205→        
206→        return testName;
207→    }
208→    
209→    return testLine.Trim();
210→}
