 29→        try
 30→        {
 31→            // Clean previous test results
 32→            var testResultsPath = Path.Combine("tests", "Six.KeycloakAdmin.Tests.Integration", "TestResults");
 33→            if (Directory.Exists(testResultsPath))
 34→            {
 35→                ctx.Status("Cleaning previous test results...");
 36→                Directory.Delete(testResultsPath, true);
 37→            }
 38→
 39→            // Find all test projects
 40→            var testProjects = Directory.GetFiles("tests", "*.Tests*.csproj", SearchOption.AllDirectories)
 41→                .Where(p => !p.Contains("bin") && !p.Contains("obj"))
 42→                .ToArray();
 43→
 44→            if (testProjects.Length == 0)
 45→            {
 46→                AnsiConsole.MarkupLine("[red]No test projects found![/]");
 47→                return;
 48→            }
 49→
 50→            AnsiConsole.MarkupLine($"[green]Found {testProjects.Length} test project(s)[/]");
 51→            AnsiConsole.WriteLine();
 52→
 53→            var totalLinesCovered = 0;
 54→            var totalLinesValid = 0;
 55→            var totalBranchesCovered = 0;
 56→            var totalBranchesValid = 0;
 57→
 58→            foreach (var project in testProjects)
 59→            {
 60→                var projectName = Path.GetFileNameWithoutExtension(project);
 61→                ctx.Status($"Running tests with coverage for [yellow]{projectName}[/]...");
 62→
 63→                // Run tests with coverage (using default results directory)
 64→                var projectDir = Path.GetDirectoryName(project) ?? ".";
 65→                var testResultsDir = Path.Combine(projectDir, "TestResults");
 66→                
 67→                var result = await Cli.Wrap("dotnet")
 68→                    .WithArguments($"test \"{project}\" --collect:\"XPlat Code Coverage\" --results-directory \"{testResultsDir}\" --verbosity minimal")
 69→                    .WithValidation(CommandResultValidation.None)
 70→                    .ExecuteBufferedAsync();
 71→
 72→                if (result.ExitCode != 0)
 73→                {
 74→                    AnsiConsole.MarkupLine($"[red]Tests failed for {projectName}[/]");
 75→                    continue;
 76→                }
 77→
 78→                // Find and parse coverage files, then move to timestamped directory
 79→                var coverageFiles = Directory.GetFiles(testResultsDir, "coverage.cobertura.xml", SearchOption.AllDirectories);
 80→                
 81→                if (coverageFiles.Length > 0)
 82→                {
 83→                    // Create timestamped directory for this test run
 84→                    var timestamp = DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss");
 85→                    var guid = Guid.NewGuid().ToString("N")[..8];
 86→                    var timestampedDir = Path.Combine(testResultsDir, $"{timestamp}-{guid}");
 87→                    Directory.CreateDirectory(timestampedDir);
 88→                    
 89→                    // Move coverage files to timestamped directory
 90→                    foreach (var coverageFile in coverageFiles)
 91→                    {
 92→                        var originalDir = Path.GetDirectoryName(coverageFile)!;
 93→                        var fileName = Path.GetFileName(coverageFile);
 94→                        var newPath = Path.Combine(timestampedDir, fileName);
 95→                        
 96→                        // Copy coverage file
 97→                        File.Copy(coverageFile, newPath, true);
 98→                        
 99→                        // Copy any other files from the original directory (json, etc.)
100→                        var otherFiles = Directory.GetFiles(originalDir, "*", SearchOption.TopDirectoryOnly)
101→                            .Where(f => !f.EndsWith("coverage.cobertura.xml"));
102→                        
103→                        foreach (var otherFile in otherFiles)
104→                        {
105→                            var otherFileName = Path.GetFileName(otherFile);
106→                            var otherNewPath = Path.Combine(timestampedDir, otherFileName);
107→                            File.Copy(otherFile, otherNewPath, true);
108→                        }
109→                        
110→                        // Clean up original directory
111→                        try
112→                        {
113→                            Directory.Delete(originalDir, true);
114→                        }
115→                        catch
116→                        {
117→                            // Ignore cleanup errors
118→                        }
119→                    }
120→                    
121→                    // Update coverage files array to point to new location
122→                    coverageFiles = Directory.GetFiles(timestampedDir, "coverage.cobertura.xml", SearchOption.TopDirectoryOnly);
123→                }
124→                
125→                if (coverageFiles.Length > 0)
126→                {
127→                    var latestCoverage = coverageFiles.OrderByDescending(f => File.GetLastWriteTime(f)).First();
128→                    var doc = XDocument.Load(latestCoverage);
129→                    var coverage = doc.Root;
130→
131→                    if (coverage != null)
132→                    {
133→                        var linesCovered = int.Parse(coverage.Attribute("lines-covered")?.Value ?? "0");
134→                        var linesValid = int.Parse(coverage.Attribute("lines-valid")?.Value ?? "0");
135→                        var branchesCovered = int.Parse(coverage.Attribute("branches-covered")?.Value ?? "0");
136→                        var branchesValid = int.Parse(coverage.Attribute("branches-valid")?.Value ?? "0");
137→
138→                        totalLinesCovered += linesCovered;
139→                        totalLinesValid += linesValid;
140→                        totalBranchesCovered += branchesCovered;
141→                        totalBranchesValid += branchesValid;
142→
143→                        var lineRate = double.Parse(coverage.Attribute("line-rate")?.Value ?? "0");
144→                        var branchRate = double.Parse(coverage.Attribute("branch-rate")?.Value ?? "0");
145→
146→                        AnsiConsole.MarkupLine($"[cyan]{projectName}[/] - Lines: {lineRate:P1}, Branches: {branchRate:P1}");
147→                    }
148→                }
149→            }
150→
151→            // Display overall coverage
152→            AnsiConsole.WriteLine();
153→            var rule = new Rule("[yellow]Overall Coverage Summary[/]")
154→                .RuleStyle("grey")
155→                .LeftJustified();
156→            AnsiConsole.Write(rule);
157→
158→            var overallLineRate = totalLinesValid > 0 ? (double)totalLinesCovered / totalLinesValid : 0;
159→            var overallBranchRate = totalBranchesValid > 0 ? (double)totalBranchesCovered / totalBranchesValid : 0;
160→
161→            var table = new Table()
162→                .Border(TableBorder.Rounded)
163→                .AddColumn("Metric")
164→                .AddColumn("Coverage")
165→                .AddColumn("Details");
166→
167→            var lineColor = overallLineRate >= 0.8 ? "green" : overallLineRate >= 0.6 ? "yellow" : "red";
168→            var branchColor = overallBranchRate >= 0.8 ? "green" : overallBranchRate >= 0.6 ? "yellow" : "red";
169→
170→            table.AddRow(
171→                "Lines",
172→                $"[{lineColor}]{overallLineRate:P1}[/]",
173→                $"{totalLinesCovered}/{totalLinesValid}"
174→            );
175→            
176→            table.AddRow(
177→                "Branches",
178→                $"[{branchColor}]{overallBranchRate:P1}[/]",
179→                $"{totalBranchesCovered}/{totalBranchesValid}"
180→            );
181→
182→            AnsiConsole.Write(table);
183→
184→            // Recommendations
185→            AnsiConsole.WriteLine();
186→            if (overallLineRate < 0.8 || overallBranchRate < 0.8)
187→            {
188→                var panel = new Panel("[yellow]⚠ Coverage Recommendations:[/]\n" +
189→                    (overallLineRate < 0.8 ? "• Line coverage is below 80%. Consider adding more tests.\n" : "") +
190→                    (overallBranchRate < 0.8 ? "• Branch coverage is below 80%. Consider testing edge cases." : ""))
191→                    .Border(BoxBorder.Rounded)
192→                    .BorderColor(Color.Yellow);
193→                AnsiConsole.Write(panel);
194→            }
195→            else
196→            {
197→                var panel = new Panel("[green]✅ Excellent coverage! Keep up the good work.[/]")
198→                    .Border(BoxBorder.Rounded)
199→                    .BorderColor(Color.Green);
200→                AnsiConsole.Write(panel);
201→            }
202→        }
203→        catch (Exception ex)
204→        {
205→            AnsiConsole.MarkupLine($"[red]Error: {ex.Message}[/]");
206→            Environment.Exit(1);
207→        }
208→    });
