 23→}
 24→
 25→// Generate detailed coverage reports
 26→await AnsiConsole.Status()
 27→    .Spinner(Spinner.Known.Dots)
 28→    .StartAsync("Generating coverage reports...", async ctx =>
 29→    {
 30→        try
 31→        {
 32→            // Find all coverage files in timestamped directories
 33→            var coverageFiles = Directory.GetFiles(".", "coverage.cobertura.xml", SearchOption.AllDirectories)
 34→                .Where(f => !f.Contains("bin") && f.Contains("TestResults"))
 35→                .OrderByDescending(f => File.GetLastWriteTime(f))
