 41→                return;
 42→            }
 43→
 44→            AnsiConsole.MarkupLine($"[green]Found {coverageFiles.Length} coverage file(s)[/]");
 45→            
 46→            // Use the latest coverage file's directory for HTML reports
 47→            var latestCoverageFile = coverageFiles[0];
 48→            var latestCoverageDir = Path.GetDirectoryName(latestCoverageFile)!;
 49→            
 50→            AnsiConsole.MarkupLine($"[yellow]Using latest coverage from: {Path.GetFileName(latestCoverageDir)}[/]");
 51→
 52→            // HTML reports will be generated in the same timestamped directory
 53→            var htmlReportsDir = Path.Combine(latestCoverageDir, "html-report");
