 62→            
 63→            var reportGeneratorPath = Path.Combine(
 64→                Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
 65→                ".nuget", "packages", "reportgenerator", "5.3.11", "tools", "net8.0", "ReportGenerator.dll"
 66→            );
 67→
 68→            if (!File.Exists(reportGeneratorPath))
 69→            {
 70→                // Try to restore the package first
 71→                await Cli.Wrap("dotnet")
 72→                    .WithArguments("tool install --global dotnet-reportgenerator-globaltool")
 73→                    .WithValidation(CommandResultValidation.None)
 74→                    .ExecuteBufferedAsync();
 75→
 76→                // Use the global tool instead
 77→                var result = await Cli.Wrap("reportgenerator")
 78→                    .WithArguments($"-reports:\"{latestCoverageFile}\" -targetdir:\"{htmlReportsDir}\" -reporttypes:Html;Cobertura;JsonSummary")
 79→                    .WithValidation(CommandResultValidation.None)
 80→                    .ExecuteBufferedAsync();
 81→            }
 82→            else
 83→            {
 84→                var result = await Cli.Wrap("dotnet")
 85→                    .WithArguments($"\"{reportGeneratorPath}\" -reports:\"{latestCoverageFile}\" -targetdir:\"{htmlReportsDir}\" -reporttypes:Html;Cobertura;JsonSummary")
 86→                    .WithValidation(CommandResultValidation.None)
 87→                    .ExecuteBufferedAsync();
 88→            }
