 90→            // Parse and display coverage summary
 91→            ctx.Status("Analyzing coverage data...");
 92→            
 93→            var summaryFile = Path.Combine(htmlReportsDir, "Summary.json");
 94→            if (File.Exists(summaryFile))
 95→            {
 96→                var summaryJson = await File.ReadAllTextAsync(summaryFile);
 97→                // Simple JSON parsing without additional dependencies
 98→                var lineRateMatch = System.Text.RegularExpressions.Regex.Match(summaryJson, @"""linecoverage""\s*:\s*([\d.]+)");
 99→                var branchRateMatch = System.Text.RegularExpressions.Regex.Match(summaryJson, @"""branchcoverage""\s*:\s*([\d.]+)");
100→                
101→                if (lineRateMatch.Success && branchRateMatch.Success)
102→                {
103→                    var lineRate = double.Parse(lineRateMatch.Groups[1].Value) / 100;
104→                    var branchRate = double.Parse(branchRateMatch.Groups[1].Value) / 100;
105→                    
106→                    DisplayCoverageSummary(lineRate, branchRate);
107→                }
108→            }
109→            else
110→            {
111→                // Fallback to parsing original Cobertura XML
112→                var doc = XDocument.Load(latestCoverageFile);
113→                var coverage = doc.Root;
114→                
115→                if (coverage != null)
116→                {
117→                    var lineRate = double.Parse(coverage.Attribute("line-rate")?.Value ?? "0");
118→                    var branchRate = double.Parse(coverage.Attribute("branch-rate")?.Value ?? "0");
119→                    
120→                    DisplayCoverageSummary(lineRate, branchRate);
121→                }
122→            }
123→
124→            // Display report location
125→            var htmlReport = Path.Combine(htmlReportsDir, "index.html");
126→            if (File.Exists(htmlReport))
