128→                AnsiConsole.WriteLine();
129→                var timestampedDirName = Path.GetFileName(latestCoverageDir);
130→                var panel = new Panel($"[green]HTML Report Generated![/]\n\nTimestamp: [yellow]{timestampedDirName}[/]\nOpen in browser:\n[link]{Path.GetFullPath(htmlReport)}[/]")
131→                    .Border(BoxBorder.Rounded)
132→                    .BorderColor(Color.Green);
133→                AnsiConsole.Write(panel);
134→                
135→                // Try to open in default browser
136→                ctx.Status("Opening report in browser...");
137→                try
138→                {
139→                    await Cli.Wrap("cmd")
140→                        .WithArguments($"/c start \"\" \"{Path.GetFullPath(htmlReport)}\"")
141→                        .WithValidation(CommandResultValidation.None)
142→                        .ExecuteAsync();
143→                }
144→                catch
145→                {
146→                    // Ignore if browser launch fails
147→                }
148→                
149→                // Clean up any temporary coverage-reports directory in solution root
150→                ctx.Status("Cleaning up temporary files...");
151→                var tempCoverageReportsDir = "coverage-reports";
152→                if (Directory.Exists(tempCoverageReportsDir))
153→                {
154→                    try
155→                    {
156→                        Directory.Delete(tempCoverageReportsDir, true);
157→                        AnsiConsole.MarkupLine("[dim]Cleaned up temporary coverage-reports directory[/]");
158→                    }
159→                    catch (Exception ex)
160→                    {
161→                        AnsiConsole.MarkupLine($"[yellow]Warning: Could not clean up temporary directory: {ex.Message}[/]");
162→                    }
163→                }
164→            }
165→        }
166→        catch (Exception ex)
167→        {
168→            AnsiConsole.MarkupLine($"[red]Error: {ex.Message}[/]");
169→            Environment.Exit(1);
170→        }
171→    });
