173→void DisplayCoverageSummary(double lineRate, double branchRate)
174→{
175→    AnsiConsole.WriteLine();
176→    var rule = new Rule("[yellow]Coverage Summary[/]")
177→        .RuleStyle("grey")
178→        .LeftJustified();
179→    AnsiConsole.Write(rule);
180→
181→    var chart = new BarChart()
182→        .Width(60)
183→        .Label("[green]Code Coverage[/]")
184→        .CenterLabel();
185→
186→    var lineColor = lineRate >= 0.8 ? Color.Green : lineRate >= 0.6 ? Color.Yellow : Color.Red;
187→    var branchColor = branchRate >= 0.8 ? Color.Green : branchRate >= 0.6 ? Color.Yellow : Color.Red;
188→
189→    chart.AddItem("Lines", lineRate * 100, lineColor);
190→    chart.AddItem("Branches", branchRate * 100, branchColor);
191→
192→    AnsiConsole.Write(chart);
193→
194→    // Display detailed metrics
195→    var table = new Table()
196→        .Border(TableBorder.Rounded)
197→        .AddColumn("Metric")
198→        .AddColumn("Coverage")
199→        .AddColumn("Status");
200→
201→    table.AddRow(
202→        "Line Coverage",
203→        $"{lineRate:P1}",
204→        lineRate >= 0.8 ? "[green]✓ Good[/]" : lineRate >= 0.6 ? "[yellow]⚠ Fair[/]" : "[red]✗ Poor[/]"
205→    );
206→    
207→    table.AddRow(
208→        "Branch Coverage",
209→        $"{branchRate:P1}",
210→        branchRate >= 0.8 ? "[green]✓ Good[/]" : branchRate >= 0.6 ? "[yellow]⚠ Fair[/]" : "[red]✗ Poor[/]"
211→    );
212→
213→    AnsiConsole.Write(table);
214→}
215→
216→AnsiConsole.MarkupLine("[green]Report generation completed![/]");
