 35→// Resolve paths - find the script location from args[0] or working directory
 36→var repoRoot = ResolveRepoRoot();
 37→var rustWorkspaceDir = Path.Combine(repoRoot, "libs-rust");
 38→var rustCargo = Path.Combine(rustWorkspaceDir, "Cargo.toml");
