 42→static string ResolveRepoRoot()
 43→{
 44→    // Try to find repo root by looking for libs-rust/Cargo.toml
 45→    var cwd = Directory.GetCurrentDirectory();
 46→
 47→    // Check if we're in the scripts directory
 48→    var parent = Path.GetDirectoryName(cwd);
 49→    if (parent != null && File.Exists(Path.Combine(parent, "libs-rust", "Cargo.toml")))
 50→    {
 51→        return parent;
 52→    }
 53→
 54→    // Check if we're in the repo root
 55→    if (File.Exists(Path.Combine(cwd, "libs-rust", "Cargo.toml")))
 56→    {
 57→        return cwd;
 58→    }
 59→
 60→    // Check if we're in libs/RayX.* directory
 61→    var grandparent = Path.GetDirectoryName(parent ?? cwd);
 62→    if (grandparent != null && File.Exists(Path.Combine(grandparent, "libs-rust", "Cargo.toml")))
 63→    {
 64→        return grandparent;
 65→    }
 66→
 67→    // Final fallback: traverse up looking for libs-rust/Cargo.toml
 68→    var dir = cwd;
 69→    while (dir != null)
 70→    {
 71→        if (File.Exists(Path.Combine(dir, "libs-rust", "Cargo.toml")))
 72→        {
 73→            return dir;
 74→        }
 75→        dir = Path.GetDirectoryName(dir);
 76→    }
 77→
 78→    throw new InvalidOperationException("Could not find repository root. Make sure libs-rust/Cargo.toml exists.");
 79→}
