 99→// Determine artifact output directory
100→var artefactDir = Path.Combine(artefactsRootDir, $"{platform.OsName}-{platform.Architecture}");
101→var nativeTargetDir = Path.Combine(rustWorkspaceDir, $"target-{platform.OsName}-{platform.Architecture}");
102→var nativeLibName = platform.GetNativeLibraryName(NativeCrateName);
