104→// For cross-compilation, cargo puts artifacts under {target-dir}/{target}/release/
105→var nativeLibPath = platform.RequiresCrossCompilation
106→    ? Path.Combine(nativeTargetDir, platform.RustTarget, "release", nativeLibName)
107→    : Path.Combine(nativeTargetDir, "release", nativeLibName);
