110→Console.WriteLine();
111→PrintHeader("Build Configuration");
112→PrintInfo($"Artifacts directory: {artefactDir}");
113→PrintInfo($"Target directory: {nativeTargetDir}");
114→PrintInfo($"Native library: {nativeLibName}");
