116→
117→// Load build info and collect current checksums
118→PrintHeader("Checking Source Changes");
119→var buildInfo = BuildInfoStorage.Load(buildInfoPath);
120→var currentChecksums = ChecksumCollector.Collect(rustWorkspaceDir, NativeCrateName);
121→
122→var sourceChanged = ChecksumCollector.HasDifferences(buildInfo.Checksums, currentChecksums, out var changedFiles);
123→var platformChanged = !string.Equals(buildInfo.Platform, $"{platform.OsName}-{platform.Architecture}", StringComparison.OrdinalIgnoreCase);
124→var versionChanged = !string.IsNullOrWhiteSpace(options.Version) && !string.Equals(buildInfo.Version, options.Version, StringComparison.OrdinalIgnoreCase);
125→var rustArtifactMissing = !File.Exists(nativeLibPath);
126→var finalArtifactMissing = !File.Exists(finalArtifactPath);
127→
128→var needsNativeBuild = options.Force || sourceChanged || platformChanged || versionChanged || rustArtifactMissing;
129→var needsCopyOnly = !needsNativeBuild && finalArtifactMissing && File.Exists(nativeLibPath);
130→
131→if (options.Force)
132→{
133→    PrintInfo("Build forced via --force flag");
134→}
135→else if (sourceChanged)
136→{
137→    PrintInfo($"Source changes detected ({changedFiles.Count} file(s) changed):");
138→    foreach (var file in changedFiles.Take(5))
139→    {
140→        PrintInfo($"  - {file}");
141→    }
142→    if (changedFiles.Count > 5)
143→    {
144→        PrintInfo($"  ... and {changedFiles.Count - 5} more");
145→    }
146→}
147→else if (platformChanged)
148→{
149→    PrintInfo($"Platform changed from '{buildInfo.Platform}' to '{platform.OsName}-{platform.Architecture}'");
150→}
151→else if (versionChanged)
152→{
153→    PrintInfo($"Version changed from '{buildInfo.Version}' to '{options.Version}'");
154→}
155→else if (rustArtifactMissing)
156→{
157→    PrintInfo($"Rust build artifact not found: {nativeLibPath}");
158→}
159→else if (needsCopyOnly)
160→{
161→    PrintInfo($"Final artifact missing, will copy from Rust target: {finalArtifactPath}");
162→}
163→else if (finalArtifactMissing)
164→{
165→    PrintInfo($"Final artifact not found: {finalArtifactPath}");
166→    needsNativeBuild = true;
167→}
168→else
169→{
170→    PrintSuccess("No changes detected - native library is up-to-date");
171→    Console.WriteLine();
172→    return 0;
173→}
174→
175→Console.WriteLine();
176→
177→// Ensure target directory exists
178→EnsureDirectoryExists(artefactDir);
179→
180→// Build the native library (skip if we only need to copy)
181→if (needsNativeBuild)
182→{
183→    EnsureDirectoryExists(nativeTargetDir);
184→
185→    PrintHeader("Building Native Library");
186→    PrintInfo("Compiling Rust code in RELEASE mode with optimizations...");
187→
188→    var buildArgs = new List<string>
189→    {
190→        "build",
191→        "--release",
192→        "--package", NativeCrateName,
193→        "--manifest-path", rustCargo,
194→        "--target-dir", nativeTargetDir,
195→    };
196→
197→    // Add target triple for cross-compilation
198→    if (platform.RequiresCrossCompilation)
199→    {
200→        buildArgs.Add("--target");
201→        buildArgs.Add(platform.RustTarget);
202→    }
203→
204→    // Add profile optimizations for smallest/fastest release build
205→    var cargoEnv = new Dictionary<string, string>
206→    {
207→        ["CARGO_PROFILE_RELEASE_LTO"] = "true",
208→        ["CARGO_PROFILE_RELEASE_CODEGEN_UNITS"] = "1",
209→        ["CARGO_PROFILE_RELEASE_STRIP"] = "symbols",
210→        ["CARGO_PROFILE_RELEASE_OPT_LEVEL"] = "3",
211→        ["CARGO_PROFILE_RELEASE_PANIC"] = "abort"
212→    };
213→
214→    // Set version as environment variable for Rust build if provided
215→    if (!string.IsNullOrWhiteSpace(options.Version))
216→    {
217→        cargoEnv["WIG_WRY_VERSION"] = options.Version;
218→    }
219→
220→    var result = RunProcess("cargo", string.Join(" ", buildArgs), rustWorkspaceDir, cargoEnv, options.Verbose);
221→
222→    if (result != 0)
223→    {
224→        PrintError("Failed to build native library");
225→        return result;
226→    }
227→
228→    if (!File.Exists(nativeLibPath))
229→    {
230→        PrintError($"Expected native artifact not found: {nativeLibPath}");
231→        return 1;
232→    }
233→
234→    PrintSuccess("Native library compiled successfully");
235→    Console.WriteLine();
236→}
237→
238→// Copy artifacts to artefacts-rust directory
239→PrintHeader("Copying Artifacts");
240→
241→var finalArtifactName = platform.GetFinalArtifactName(NativeCrateName);
242→var destPath = Path.Combine(artefactDir, finalArtifactName);
243→
244→File.Copy(nativeLibPath, destPath, overwrite: true);
245→PrintInfo($"Copied: {nativeLibName} -> {destPath}");
246→
247→// Also check for and copy PDB/debug symbols if they exist
248→var debugExtensions = new[] { ".pdb", ".dSYM", ".debug" };
249→foreach (var ext in debugExtensions)
250→{
251→    var debugSource = Path.ChangeExtension(nativeLibPath, ext);
252→    if (File.Exists(debugSource))
