254→        var debugDest = Path.Combine(artefactDir, Path.ChangeExtension(finalArtifactName, ext));
255→        File.Copy(debugSource, debugDest, overwrite: true);
256→        PrintInfo($"Copied debug symbols: {Path.GetFileName(debugSource)}");
