268→
269→Console.WriteLine();
270→
271→// Update build info (only when we actually built, not copy-only)
272→if (needsNativeBuild)
273→{
274→    PrintHeader("Updating Build Info");
275→
276→    buildInfo.Platform = $"{platform.OsName}-{platform.Architecture}";
277→    buildInfo.Profile = "release";
278→    buildInfo.Version = options.Version ?? string.Empty;
279→    buildInfo.Checksums = currentChecksums;
280→    buildInfo.LastBuildTime = DateTime.UtcNow.ToString("O");
281→
282→    BuildInfoStorage.Save(buildInfoPath, buildInfo);
283→    PrintInfo($"Updated: {buildInfoPath}");
284→
285→    Console.WriteLine();
286→    PrintSuccess("╔══════════════════════════════════════════════════════════════╗");
287→    PrintSuccess("║           Build completed successfully!                      ║");
288→    PrintSuccess("╚══════════════════════════════════════════════════════════════╝");
289→}
290→else
291→{
292→    Console.WriteLine();
293→    PrintSuccess("╔══════════════════════════════════════════════════════════════╗");
294→    PrintSuccess("║           Artifacts copied successfully!                     ║");
295→    PrintSuccess("╚══════════════════════════════════════════════════════════════╝");
296→}
297→Console.WriteLine();
