339→static int RunProcess(string fileName, string arguments, string workingDirectory, Dictionary<string, string> envVars, bool verbose)
340→{
341→    if (verbose)
342→    {
343→        Console.WriteLine($"  > {fileName} {arguments}");
344→    }
345→
346→    var startInfo = new ProcessStartInfo
347→    {
348→        FileName = fileName,
349→        Arguments = arguments,
350→        WorkingDirectory = workingDirectory,
351→        RedirectStandardOutput = true,
352→        RedirectStandardError = true,
353→        UseShellExecute = false
354→    };
355→
356→    foreach (var kvp in envVars)
357→    {
358→        startInfo.EnvironmentVariables[kvp.Key] = kvp.Value;
359→    }
360→
361→    try
362→    {
363→        using var process = Process.Start(startInfo);
364→        if (process == null)
365→        {
366→            PrintError($"Failed to start process: {fileName}");
367→            return 1;
368→        }
369→
370→        var outputTask = process.StandardOutput.ReadToEndAsync();
371→        var errorTask = process.StandardError.ReadToEndAsync();
372→
373→        process.WaitForExit();
374→
375→        var output = outputTask.Result;
376→        var error = errorTask.Result;
377→
378→        if (verbose || process.ExitCode != 0)
379→        {
380→            if (!string.IsNullOrWhiteSpace(output))
381→            {
382→                Console.WriteLine(output);
383→            }
384→            if (!string.IsNullOrWhiteSpace(error))
385→            {
386→                Console.Error.WriteLine(error);
387→            }
388→        }
389→
390→        return process.ExitCode;
391→    }
392→    catch (Exception ex)
393→    {
394→        PrintError($"Error running process: {ex.Message}");
395→        return 1;
396→    }
397→}
