399→// ============================================================================
400→// Platform Detection
401→// ============================================================================
402→
403→sealed class PlatformInfo
404→{
405→    public required string OsName { get; init; }
406→    public required string Architecture { get; init; }
407→    public required string RustTarget { get; init; }
408→
409→    /// <summary>
410→    /// Whether this platform requires cross-compilation (target triple must be specified).
411→    /// True when targeting mobile/wasm platforms, or when host OS differs from target OS.
412→    /// </summary>
413→    public bool RequiresCrossCompilation
414→    {
415→        get
416→        {
417→            // Always cross-compile for mobile/wasm/embedded targets
418→            if (OsName is "wasm" or "ios" or "ios-sim" or "android"
419→                or "watchos" or "watchos-sim" or "tvos" or "tvos-sim"
420→                or "visionos" or "visionos-sim" or "maccatalyst")
421→                return true;
422→
423→            // Cross-compile when host OS differs from target OS
424→            var hostOs = RuntimeInformation.IsOSPlatform(OSPlatform.Windows) ? "windows"
425→                : RuntimeInformation.IsOSPlatform(OSPlatform.OSX) ? "macos"
426→                : "linux";
427→            if (!string.Equals(hostOs, OsName, StringComparison.OrdinalIgnoreCase))
428→                return true;
429→
430→            // Cross-compile when host architecture differs from target architecture
431→            var hostArch = RuntimeInformation.OSArchitecture switch
432→            {
433→                System.Runtime.InteropServices.Architecture.X64 => "x64",
434→                System.Runtime.InteropServices.Architecture.X86 => "x86",
435→                System.Runtime.InteropServices.Architecture.Arm64 => "arm64",
436→                System.Runtime.InteropServices.Architecture.Arm => "arm",
437→                _ => "x64"
438→            };
439→            return !string.Equals(hostArch, Architecture, StringComparison.OrdinalIgnoreCase);
440→        }
441→    }
442→
443→    /// <summary>
444→    /// Gets the native library file name as produced by cargo.
445→    /// Cargo converts hyphens to underscores in library names.
446→    /// </summary>
447→    public string GetNativeLibraryName(string crateName)
448→    {
449→        var libName = crateName.Replace('-', '_');
450→        return OsName switch
451→        {
452→            "windows" => $"{libName}.dll",
453→            "wasm" => $"{libName}.wasm",
454→            "macos" or "maccatalyst" => $"lib{libName}.dylib",
455→            "ios" or "ios-sim" => $"lib{libName}.a",
456→            "watchos" or "watchos-sim" => $"lib{libName}.dylib",
457→            "tvos" or "tvos-sim" => $"lib{libName}.dylib",
458→            "visionos" or "visionos-sim" => $"lib{libName}.dylib",
459→            _ => $"lib{libName}.so"
460→        };
461→    }
462→
463→    /// <summary>
464→    /// Gets the final artifact name with platform/arch suffix.
465→    /// </summary>
466→    public string GetFinalArtifactName(string prefix)
467→    {
468→        var libName = prefix.Replace('-', '_');
469→        return OsName switch
470→        {
471→            "windows" => $"lib{libName}-{OsName}-{Architecture}.dll",
472→            "wasm" => $"lib{libName}-{OsName}-{Architecture}.wasm",
473→            "macos" or "maccatalyst" => $"lib{libName}-{OsName}-{Architecture}.dylib",
474→            "ios" or "ios-sim" => $"lib{libName}-{OsName}-{Architecture}.a",
475→            "watchos" or "watchos-sim" => $"lib{libName}-{OsName}-{Architecture}.dylib",
476→            "tvos" or "tvos-sim" => $"lib{libName}-{OsName}-{Architecture}.dylib",
477→            "visionos" or "visionos-sim" => $"lib{libName}-{OsName}-{Architecture}.dylib",
478→            _ => $"lib{libName}-{OsName}-{Architecture}.so"
479→        };
480→    }
481→}
482→
483→static class PlatformDetector
484→{
485→    /// <summary>
486→    /// Detects the target platform. Priority: CLI args > env vars > auto-detect
487→    /// </summary>
488→    public static PlatformInfo Detect(string? cliTargetOs, string? cliTargetArch)
489→    {
490→        // Priority 1: CLI arguments
491→        if (!string.IsNullOrWhiteSpace(cliTargetOs) && !string.IsNullOrWhiteSpace(cliTargetArch))
492→        {
493→            return CreatePlatformInfo(cliTargetOs.ToLowerInvariant(), cliTargetArch.ToLowerInvariant());
494→        }
495→
496→        // Priority 2: Environment variables
497→        var envTargetOs = Environment.GetEnvironmentVariable("WIG_WRY_TARGET_OS");
498→        var envTargetArch = Environment.GetEnvironmentVariable("WIG_WRY_TARGET_ARCH");
499→
500→        if (!string.IsNullOrWhiteSpace(envTargetOs) && !string.IsNullOrWhiteSpace(envTargetArch))
501→        {
502→            return CreatePlatformInfo(envTargetOs.ToLowerInvariant(), envTargetArch.ToLowerInvariant());
503→        }
504→
505→        // Priority 3: Auto-detect from runtime
506→        var osName = DetectOsName();
507→        var arch = DetectArchitecture();
508→
509→        return CreatePlatformInfo(osName, arch);
510→    }
511→
512→    static PlatformInfo CreatePlatformInfo(string osName, string arch)
513→    {
514→        var rustTarget = GetRustTarget(osName, arch);
515→        return new PlatformInfo
516→        {
517→            OsName = osName,
518→            Architecture = arch,
519→            RustTarget = rustTarget
520→        };
521→    }
522→
523→    static string DetectOsName()
524→    {
525→        if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
526→            return "windows";
527→
528→        if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
529→            return "macos";
530→
531→        if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
532→        {
533→            if (File.Exists("/system/build.prop"))
534→            {
535→                return "android";
536→            }
537→            return "linux";
538→        }
539→
540→        return "unix";
541→    }
542→
543→    static string DetectArchitecture()
544→    {
545→        return RuntimeInformation.OSArchitecture switch
546→        {
547→            Architecture.X64 => "x64",
548→            Architecture.X86 => "x86",
549→            Architecture.Arm64 => "arm64",
550→            Architecture.Arm => "arm",
551→            Architecture.Wasm => "wasm32",
552→            _ => "x64"
553→        };
554→    }
555→
556→    static string GetRustTarget(string osName, string arch)
557→    {
558→        return (osName, arch) switch
559→        {
560→            ("windows", "x64") => "x86_64-pc-windows-msvc",
561→            ("windows", "x86") => "i686-pc-windows-msvc",
562→            ("windows", "arm64") => "aarch64-pc-windows-msvc",
563→            ("macos", "x64") => "x86_64-apple-darwin",
564→            ("macos", "arm64") => "aarch64-apple-darwin",
565→            ("linux", "x64") => "x86_64-unknown-linux-gnu",
566→            ("linux", "arm64") => "aarch64-unknown-linux-gnu",
567→            ("linux", "arm") => "armv7-unknown-linux-gnueabihf",
568→            ("ios", "arm64") => "aarch64-apple-ios",
569→            ("ios-sim", "x64") => "x86_64-apple-ios",
570→            ("ios-sim", "arm64") => "aarch64-apple-ios-sim",
571→            ("android", "arm64") => "aarch64-linux-android",
572→            ("android", "arm") => "armv7-linux-androideabi",
573→            ("android", "x64") => "x86_64-linux-android",
574→            ("android", "x86") => "i686-linux-android",
575→            ("wasm", "wasm32") => "wasm32-unknown-unknown",
576→            (_, "wasm32") => "wasm32-unknown-unknown",
577→            _ => "x86_64-unknown-linux-gnu"
578→        };
579→    }
580→}
