583→// Build Options
584→// ============================================================================
585→
586→sealed class BuildOptions
587→{
588→    public string? Version { get; set; }
589→    public string? TargetOs { get; set; }
590→    public string? TargetArch { get; set; }
591→    public string OutputDirectory { get; set; } = string.Empty;
592→    public bool Force { get; set; }
593→    public bool Verbose { get; set; }
594→
595→    public static BuildOptions Parse(string[] arguments)
596→    {
597→        var options = new BuildOptions();
598→
599→        for (var i = 0; i < arguments.Length; i++)
600→        {
601→            var arg = arguments[i];
602→
603→            switch (arg)
604→            {
605→                case "-v":
606→                case "--version":
607→                    options.Version = GetValue(arguments, ref i);
608→                    break;
609→                case "--target-os":
610→                    options.TargetOs = GetValue(arguments, ref i);
611→                    break;
612→                case "--target-arch":
613→                    options.TargetArch = GetValue(arguments, ref i);
614→                    break;
615→                case "-o":
616→                case "--out-dir":
617→                    options.OutputDirectory = Path.GetFullPath(GetValue(arguments, ref i));
618→                    break;
619→                case "-f":
620→                case "--force":
621→                    options.Force = true;
622→                    break;
623→                case "--verbose":
624→                    options.Verbose = true;
625→                    break;
626→                case "-h":
627→                case "--help":
628→                    PrintHelp();
629→                    Environment.Exit(0);
630→                    break;
631→                default:
632→                    if (arg.StartsWith('-'))
