728→// ============================================================================
729→// Checksum Collector
730→// ============================================================================
731→
732→static class ChecksumCollector
733→{
734→    public static Dictionary<string, string> Collect(string workspaceDir, string targetCrate)
735→    {
736→        var checksums = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
737→
738→        // Add workspace Cargo.toml
739→        AddFile(checksums, Path.Combine(workspaceDir, "Cargo.toml"), "Cargo.toml");
740→
741→        // Add the target crate's Cargo.toml and src files
742→        var crateDir = Path.Combine(workspaceDir, targetCrate);
743→        if (Directory.Exists(crateDir))
744→        {
745→            var crateCargo = Path.Combine(crateDir, "Cargo.toml");
746→            if (File.Exists(crateCargo))
747→            {
748→                AddFile(checksums, crateCargo, $"{targetCrate}/Cargo.toml");
749→            }
750→
751→            var crateSrc = Path.Combine(crateDir, "src");
752→            if (Directory.Exists(crateSrc))
753→            {
754→                AddDirectory(checksums, crateSrc, $"{targetCrate}/src");
755→            }
756→        }
757→
758→        return checksums;
759→    }
760→
761→    public static bool HasDifferences(
762→        Dictionary<string, string> previous,
763→        Dictionary<string, string> current,
764→        out List<string> changedFiles)
765→    {
766→        changedFiles = [];
767→
768→        foreach (var kvp in current)
769→        {
770→            if (!previous.TryGetValue(kvp.Key, out var oldChecksum))
771→            {
772→                changedFiles.Add($"+ {kvp.Key}");
773→            }
774→            else if (!oldChecksum.Equals(kvp.Value, StringComparison.OrdinalIgnoreCase))
775→            {
776→                changedFiles.Add($"~ {kvp.Key}");
777→            }
778→        }
779→
780→        foreach (var kvp in previous)
781→        {
782→            if (!current.ContainsKey(kvp.Key))
783→            {
784→                changedFiles.Add($"- {kvp.Key}");
785→            }
786→        }
787→
788→        return changedFiles.Count > 0;
789→    }
790→
791→    static void AddDirectory(Dictionary<string, string> checksums, string directory, string prefix)
792→    {
793→        if (!Directory.Exists(directory))
794→        {
795→            return;
796→        }
797→
798→        foreach (var file in Directory.EnumerateFiles(directory, "*.*", SearchOption.AllDirectories))
799→        {
800→            var ext = Path.GetExtension(file).ToLowerInvariant();
801→            if (ext != ".rs" && ext != ".toml")
802→            {
803→                continue;
804→            }
805→
806→            var relative = Path.GetRelativePath(directory, file).Replace('\\', '/');
807→            var key = $"{prefix}/{relative}";
808→            checksums[key] = ComputeChecksum(file);
809→        }
810→    }
811→
812→    static void AddFile(Dictionary<string, string> checksums, string path, string key)
813→    {
814→        if (File.Exists(path))
815→        {
816→            checksums[key] = ComputeChecksum(path);
817→        }
818→    }
819→
820→    static string ComputeChecksum(string file)
821→    {
822→        using var stream = File.OpenRead(file);
823→        var hash = SHA256.HashData(stream);
824→        return Convert.ToHexString(hash);
825→    }
826→}
