  1→#!/usr/bin/env dotnet
  2→
  3→#:sdk Microsoft.NET.Sdk
  4→
  5→#:property TargetFramework=net10.0
  6→#:property LangVersion=14
  7→#:property Nullable=enable
  8→#:property ImplicitUsings=enable
  9→#:property PublishAot=false
 10→
 11→using System.Runtime.InteropServices;
 12→
 13→/// <summary>
 14→/// Copies native Avalonia WebView libraries from artefacts-rust/ to the specified output directory.
 15→/// Automatically detects the current platform and copies the appropriate .dll/.so/.dylib.
 16→/// </summary>
 17→/// <remarks>
 18→/// Usage: dotnet scripts/copy-native-libs.cs -- --output-dir &lt;path&gt; [--verbose]
 19→///
 20→/// This script is designed to be called from MSBuild targets to ensure native
 21→/// libraries are available in the test/application output directory.
 22→///
 23→/// Libraries copied:
 24→/// - libavalonia_webview (Avalonia WebView - Wry-based web browser control)
 25→/// </remarks>
 26→
 27→var options = CopyOptions.Parse(args);
 28→
 29→if (options.ShowHelp)
 30→{
 31→    PrintHelp();
 32→    return 0;
 33→}
 34→
 35→if (string.IsNullOrWhiteSpace(options.OutputDir))
 36→{
 37→    PrintError("Output directory is required. Use --output-dir <path>");
 38→    PrintHelp();
 39→    return 1;
 40→}
 41→
 42→// Resolve paths
 43→var repoRoot = ResolveRepoRoot();
 44→var artefactsRoot = Path.Combine(repoRoot, "artefacts-rust");
 45→
 46→if (!Directory.Exists(artefactsRoot))
 47→{
 48→    PrintError($"Artefacts directory not found: {artefactsRoot}");
 49→    PrintInfo("Run 'dotnet scripts/build-native.cs' first to build the native library.");
 50→    return 1;
 51→}
 52→
 53→// Detect platform (CLI args > env vars > auto-detect)
 54→var platform = PlatformDetector.Detect(options.TargetOs, options.TargetArch);
 55→
 56→if (options.Verbose)
 57→{
 58→    PrintInfo($"Detected platform: {platform.OsName}-{platform.Architecture}");
 59→    PrintInfo($"Artefacts root: {artefactsRoot}");
 60→    PrintInfo($"Output directory: {options.OutputDir}");
 61→}
 62→
 63→// Ensure output directory exists
 64→if (!Directory.Exists(options.OutputDir))
 65→{
 66→    Directory.CreateDirectory(options.OutputDir);
 67→}
 68→
 69→// Define all library mappings
 70→// Each entry maps: (sourceDir relative to artefacts-rust, sourceFilePattern, destLibraryName for C#)
 71→// The destLibraryName is what C# expects (without extension - extension added based on platform)
 72→// Note: Windows cargo outputs without 'lib' prefix, Linux/macOS with 'lib' prefix
 73→var libraryMappings = new LibraryMapping[]
 74→{
 75→    // Avalonia WebView: artefacts-rust/{platform}/libavalonia_webview-{platform}.dll -> libavalonia_webview.dll
 76→    // Wry-based cross-platform web browser control for Avalonia
 77→    new("", "libavalonia_webview", "libavalonia_webview"),
 78→};
 79→
 80→var copiedCount = 0;
 81→var copiedLibraries = new List<string>();
 82→var platformKey = $"{platform.OsName}-{platform.Architecture}";
 83→
 84→// Copy libraries for the current platform
 85→foreach (var mapping in libraryMappings)
 86→{
 87→    var sourceDir = string.IsNullOrEmpty(mapping.SourceSubDir)
 88→        ? Path.Combine(artefactsRoot, platformKey)
 89→        : Path.Combine(artefactsRoot, mapping.SourceSubDir, platformKey);
 90→
 91→    if (!Directory.Exists(sourceDir))
 92→    {
 93→        if (options.Verbose)
 94→            PrintInfo($"Source directory not found: {sourceDir}");
 95→        continue;
 96→    }
 97→
 98→    var sourceFileName = GetSourceFileName(mapping.SourcePrefix, platformKey, platform.OsName);
 99→    var sourcePath = Path.Combine(sourceDir, sourceFileName);
100→
101→    if (!File.Exists(sourcePath))
102→    {
103→        if (options.Verbose)
104→            PrintInfo($"Source file not found: {sourcePath}");
105→        continue;
106→    }
107→
108→    var destFileName = GetDestFileName(mapping.DestLibraryName, platform.OsName);
109→    var destPath = Path.Combine(options.OutputDir, destFileName);
110→
111→    try
112→    {
113→        File.Copy(sourcePath, destPath, overwrite: true);
114→        copiedCount++;
115→        copiedLibraries.Add(mapping.DestLibraryName);
116→
117→        if (options.Verbose)
118→            PrintSuccess($"Copied: {sourceFileName} -> {destFileName}");
119→    }
120→    catch (Exception ex)
121→    {
122→        PrintWarning($"Failed to copy {sourceFileName}: {ex.Message}");
123→    }
124→
125→    // Also copy to runtimes/{rid}/native/ for proper .NET resolution
126→    var runtimeId = platform.GetRuntimeIdentifier();
127→    var runtimeNativeDir = Path.Combine(options.OutputDir, "runtimes", runtimeId, "native");
128→
129→    try
130→    {
131→        if (!Directory.Exists(runtimeNativeDir))
132→        {
133→            Directory.CreateDirectory(runtimeNativeDir);
134→        }
135→
136→        var runtimeDestPath = Path.Combine(runtimeNativeDir, destFileName);
137→        File.Copy(sourcePath, runtimeDestPath, overwrite: true);
138→
139→        if (options.Verbose)
140→            PrintSuccess($"Copied to runtimes: {sourceFileName} -> runtimes/{runtimeId}/native/{destFileName}");
141→    }
142→    catch (Exception ex)
143→    {
144→        if (options.Verbose)
145→            PrintWarning($"Failed to copy to runtimes: {ex.Message}");
146→    }
147→}
148→
149→if (copiedCount == 0)
150→{
151→    PrintWarning("No native libraries found in artefacts-rust/");
152→    PrintInfo("Build the native library first:");
153→    PrintInfo("  dotnet scripts/build-native.cs");
154→    return 0;
155→}
156→
157→if (!options.Verbose)
158→{
159→    PrintSuccess($"Native libraries copied to output ({string.Join(", ", copiedLibraries.Distinct())})");
160→}
161→
162→return 0;
163→
164→// ============================================================================
165→// Helper Methods
166→// ============================================================================
167→
168→static string GetSourceFileName(string prefix, string platformKey, string osName)
169→{
170→    var ext = osName switch
171→    {
172→        "windows" => "dll",
173→        "wasm" => "wasm",
174→        "macos" or "maccatalyst" => "dylib",
175→        "ios" or "ios-sim" => "a",
176→        _ => "so"
177→    };
178→
179→    // All native libraries use 'lib' prefix on all platforms
180→    // If prefix already starts with 'lib', don't add another one
181→    if (!prefix.StartsWith("lib"))
182→    {
183→        return $"lib{prefix}-{platformKey}.{ext}";
184→    }
185→
186→    return $"{prefix}-{platformKey}.{ext}";
187→}
188→
189→static string GetDestFileName(string libraryName, string osName)
190→{
191→    var ext = osName switch
192→    {
193→        "windows" => "dll",
194→        "wasm" => "wasm",
195→        "macos" or "maccatalyst" => "dylib",
196→        "ios" or "ios-sim" => "a",
197→        _ => "so"
198→    };
199→    return $"{libraryName}.{ext}";
200→}
201→
202→static string ResolveRepoRoot()
203→{
204→    var cwd = Directory.GetCurrentDirectory();
205→
206→    // Traverse up looking for artefacts-rust directory
207→    var dir = cwd;
208→    while (dir != null)
209→    {
210→        if (Directory.Exists(Path.Combine(dir, "artefacts-rust")))
211→        {
212→            return dir;
213→        }
214→        dir = Path.GetDirectoryName(dir);
215→    }
216→
217→    // Fallback: check common relative paths
218→    var candidates = new[]
219→    {
220→        cwd,
221→        Path.GetDirectoryName(cwd) ?? cwd,
222→        Path.Combine(cwd, "..", ".."),
223→        Path.Combine(cwd, "..", "..", "..")
224→    };
225→
226→    foreach (var candidate in candidates)
227→    {
228→        if (string.IsNullOrEmpty(candidate)) continue;
229→        var fullPath = Path.GetFullPath(candidate);
230→        if (Directory.Exists(Path.Combine(fullPath, "artefacts-rust")))
231→        {
232→            return fullPath;
233→        }
234→    }
235→
236→    throw new InvalidOperationException(
237→        "Could not find repository root. Ensure artefacts-rust/ directory exists.");
238→}
