315→    public static CopyOptions Parse(string[] arguments)
316→    {
317→        var options = new CopyOptions();
318→
319→        for (var i = 0; i < arguments.Length; i++)
320→        {
321→            var arg = arguments[i];
322→
323→            switch (arg)
324→            {
325→                case "-o":
326→                case "--output-dir":
327→                    options.OutputDir = GetValue(arguments, ref i);
328→                    break;
329→                case "--target-os":
330→                    options.TargetOs = GetValue(arguments, ref i);
331→                    break;
332→                case "--target-arch":
333→                    options.TargetArch = GetValue(arguments, ref i);
334→                    break;
335→                case "-v":
336→                case "--verbose":
337→                    options.Verbose = true;
338→                    break;
339→                case "-h":
340→                case "--help":
341→                    options.ShowHelp = true;
342→                    break;
343→            }
344→        }
345→
346→        return options;
347→    }
