349→    static string GetValue(string[] args, ref int index)
350→    {
351→        if (index + 1 >= args.Length)
352→        {
353→            throw new ArgumentException($"Missing value for {args[index]}");
354→        }
355→
356→        index++;
357→        return args[index];
358→    }
