361→// ============================================================================
362→// Platform Detection (matching build-native.cs)
363→// ============================================================================
364→
365→sealed class PlatformInfo
366→{
367→    public required string OsName { get; init; }
368→    public required string Architecture { get; init; }
369→    public required string RustTarget { get; init; }
370→
371→    /// <summary>
372→    /// Gets the .NET runtime identifier for this platform.
373→    /// </summary>
374→    public string GetRuntimeIdentifier() => (OsName, Architecture) switch
375→    {
376→        // Windows
377→        ("windows", "x64") => "win-x64",
378→        ("windows", "x86") => "win-x86",
379→        ("windows", "arm64") => "win-arm64",
380→
381→        // macOS
382→        ("macos", "x64") => "osx-x64",
383→        ("macos", "arm64") => "osx-arm64",
384→
385→        // Linux
386→        ("linux", "x64") => "linux-x64",
387→        ("linux", "arm64") => "linux-arm64",
388→        ("linux", "arm") => "linux-arm",
389→
390→        // iOS
391→        ("ios", "arm64") => "ios-arm64",
392→        ("ios-sim", "x64") => "iossimulator-x64",
393→        ("ios-sim", "arm64") => "iossimulator-arm64",
394→
395→        // Mac Catalyst
396→        ("maccatalyst", "x64") => "maccatalyst-x64",
397→        ("maccatalyst", "arm64") => "maccatalyst-arm64",
398→
399→        // tvOS
400→        ("tvos", "arm64") => "tvos-arm64",
401→        ("tvos-sim", "x64") => "tvossimulator-x64",
402→        ("tvos-sim", "arm64") => "tvossimulator-arm64",
403→
404→        // Android
405→        ("android", "arm64") => "android-arm64",
406→        ("android", "arm") => "android-arm",
407→        ("android", "x64") => "android-x64",
408→        ("android", "x86") => "android-x86",
409→
410→        // WebAssembly
411→        ("wasm", "wasm32") => "browser-wasm",
412→
413→        // Fallback
414→        _ => $"{OsName}-{Architecture}"
415→    };
416→}
417→
418→static class PlatformDetector
419→{
420→    /// <summary>
421→    /// Detects the target platform. Priority: CLI args > env vars > auto-detect
422→    /// </summary>
423→    public static PlatformInfo Detect(string? cliTargetOs, string? cliTargetArch)
424→    {
425→        // Priority 1: CLI arguments
426→        if (!string.IsNullOrWhiteSpace(cliTargetOs) && !string.IsNullOrWhiteSpace(cliTargetArch))
427→        {
428→            return CreatePlatformInfo(cliTargetOs.ToLowerInvariant(), cliTargetArch.ToLowerInvariant());
429→        }
430→
431→        // Priority 2: Environment variables
432→        var envTargetOs = Environment.GetEnvironmentVariable("WIG_WRY_TARGET_OS");
433→        var envTargetArch = Environment.GetEnvironmentVariable("WIG_WRY_TARGET_ARCH");
434→
435→        if (!string.IsNullOrWhiteSpace(envTargetOs) && !string.IsNullOrWhiteSpace(envTargetArch))
436→        {
437→            return CreatePlatformInfo(envTargetOs.ToLowerInvariant(), envTargetArch.ToLowerInvariant());
438→        }
439→
440→        // Priority 3: Auto-detect from runtime
441→        var osName = DetectOsName();
442→        var arch = DetectArchitecture();
443→
444→        return CreatePlatformInfo(osName, arch);
445→    }
446→
447→    static PlatformInfo CreatePlatformInfo(string osName, string arch)
448→    {
449→        var rustTarget = GetRustTarget(osName, arch);
450→        return new PlatformInfo
451→        {
452→            OsName = osName,
453→            Architecture = arch,
454→            RustTarget = rustTarget
455→        };
456→    }
457→
458→    static string DetectOsName()
459→    {
460→        // Check Windows first - ANDROID_HOME/ANDROID_SDK_ROOT env vars may be set
461→        // on Windows dev machines with Android SDK installed, so we must check
462→        // the actual OS platform before checking Android indicators
463→        if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
464→            return "windows";
465→
466→        if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
467→            return "macos";
468→
469→        if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
470→        {
471→            // On Linux, check if we're actually running on Android
472→            // /system/build.prop only exists on Android devices
473→            if (File.Exists("/system/build.prop"))
474→            {
475→                return "android";
476→            }
477→            return "linux";
478→        }
479→
480→        // Fallback
481→        return "unix";
482→    }
483→
484→    static string DetectArchitecture()
485→    {
486→        return RuntimeInformation.OSArchitecture switch
487→        {
488→            Architecture.X64 => "x64",
489→            Architecture.X86 => "x86",
490→            Architecture.Arm64 => "arm64",
491→            Architecture.Arm => "arm",
492→            Architecture.Wasm => "wasm32",
493→            _ => "x64"
494→        };
495→    }
496→
497→    static string GetRustTarget(string osName, string arch)
498→    {
499→        return (osName, arch) switch
500→        {
501→            // Windows
502→            ("windows", "x64") => "x86_64-pc-windows-msvc",
503→            ("windows", "x86") => "i686-pc-windows-msvc",
504→            ("windows", "arm64") => "aarch64-pc-windows-msvc",
505→
506→            // macOS
507→            ("macos", "x64") => "x86_64-apple-darwin",
508→            ("macos", "arm64") => "aarch64-apple-darwin",
509→
510→            // Linux
511→            ("linux", "x64") => "x86_64-unknown-linux-gnu",
512→            ("linux", "arm64") => "aarch64-unknown-linux-gnu",
513→            ("linux", "arm") => "armv7-unknown-linux-gnueabihf",
514→
515→            // iOS Device
516→            ("ios", "arm64") => "aarch64-apple-ios",
517→
518→            // iOS Simulator
519→            ("ios-sim", "x64") => "x86_64-apple-ios",
520→            ("ios-sim", "arm64") => "aarch64-apple-ios-sim",
521→
522→            // watchOS Device
523→            ("watchos", "arm64") => "aarch64-apple-watchos",
524→
525→            // watchOS Simulator
526→            ("watchos-sim", "x64") => "x86_64-apple-watchos-sim",
527→            ("watchos-sim", "arm64") => "aarch64-apple-watchos-sim",
528→
529→            // tvOS Device
530→            ("tvos", "arm64") => "aarch64-apple-tvos",
531→
532→            // tvOS Simulator
533→            ("tvos-sim", "x64") => "x86_64-apple-tvos-sim",
534→            ("tvos-sim", "arm64") => "aarch64-apple-tvos-sim",
535→
536→            // visionOS Device
537→            ("visionos", "arm64") => "aarch64-apple-visionos",
538→
539→            // visionOS Simulator
540→            ("visionos-sim", "arm64") => "aarch64-apple-visionos-sim",
541→
542→            // Mac Catalyst
543→            ("maccatalyst", "x64") => "x86_64-apple-ios-macabi",
544→            ("maccatalyst", "arm64") => "aarch64-apple-ios-macabi",
545→
546→            // Android
547→            ("android", "arm64") => "aarch64-linux-android",
548→            ("android", "arm") => "armv7-linux-androideabi",
549→            ("android", "x64") => "x86_64-linux-android",
550→            ("android", "x86") => "i686-linux-android",
551→
552→            // WebAssembly
553→            ("wasm", "wasm32") => "wasm32-unknown-unknown",
554→            (_, "wasm32") => "wasm32-unknown-unknown",
555→
556→            // Fallback
557→            _ => "x86_64-unknown-linux-gnu"
558→        };
559→    }
560→}
