163→PublishMode GetPublishMode(string[] args)
164→{
165→    if (args.Contains("--pack-only")) return PublishMode.PackOnly;
166→    if (args.Contains("--local")) return PublishMode.Local;
167→    if (args.Contains("--dev") || args.Contains("--development")) return PublishMode.Development;
168→    if (args.Contains("--staging")) return PublishMode.Staging;
169→    if (args.Contains("--prod") || args.Contains("--production")) return PublishMode.Production;
170→    return PublishMode.Local; // Default to local feed
171→}
