194→        case PublishMode.Staging:
195→          if (string.IsNullOrEmpty(stagingFeedUrl))
196→            throw new InvalidOperationException("NUGET_FEED_STAGING_URL environment variable is required for STAGING feed publishing");
197→          if (string.IsNullOrEmpty(stagingFeedUsername))
198→            throw new InvalidOperationException("NUGET_FEED_STAGING_USERNAME environment variable is required for STAGING feed publishing");
199→          if (string.IsNullOrEmpty(stagingFeedPat))
200→            throw new InvalidOperationException("NUGET_FEED_STAGING_PAT environment variable is required for STAGING feed publishing");
201→          break;
