239→List<string> DiscoverProjects(List<string> searchDirs, List<string> ignored)
240→{
241→    var projects = new List<string>();
242→    
243→    foreach (var dir in searchDirs)
244→    {
245→        if (!Directory.Exists(dir))
246→        {
247→            AnsiConsole.MarkupLine($"[yellow]Warning: Directory '{dir}' does not exist, skipping...[/]");
248→            continue;
249→        }
250→
251→        var foundProjects = Directory.GetFiles(dir, "*.csproj", SearchOption.AllDirectories)
252→            .Where(p => !ignored.Any(ignore => Path.GetFileNameWithoutExtension(p).Equals(ignore, StringComparison.OrdinalIgnoreCase)))
253→            .ToList();
254→
255→        projects.AddRange(foundProjects);
256→    }
257→
258→    return projects.OrderBy(p => Path.GetFileNameWithoutExtension(p)).ToList();
259→}
260→
261→(List<string> Packable, List<string> Skipped) PartitionByArtifacts(List<string> projects)
262→{
263→    var artefactsRoot = Path.GetFullPath("artefacts-rust");
264→    const string nativeLibBaseName = "libavalonia_webview";
265→
266→    var packable = new List<string>();
267→    var skipped = new List<string>();
268→
269→    foreach (var project in projects)
270→    {
271→        var content = File.ReadAllText(project);
272→
273→        // Not a native package — always pack
274→        if (!content.Contains("Directory.NativePackage.props"))
275→        {
276→            packable.Add(project);
277→            continue;
278→        }
279→
280→        // Native package — check if any Exists() conditions resolve to real files
281→        var hasArtifacts = Regex.Matches(content, @"Condition=""Exists\('([^']+)'\)""")
282→            .Cast<Match>()
283→            .Any(m => File.Exists(
284→                m.Groups[1].Value
285→                    .Replace("$(ArtefactsRustRoot)", artefactsRoot)
286→                    .Replace("$(NativeLibBaseName)", nativeLibBaseName)
287→                    .Replace('\\', '/')));
288→
289→        if (hasArtifacts)
290→            packable.Add(project);
291→        else
292→            skipped.Add(project);
293→    }
294→
295→    return (packable, skipped);
296→}
