316→async Task<List<PackResult>> BuildAndPackProjectsAsync(List<string> projects, string config, string outputDir)
317→{
318→    // Ensure output directory exists
319→    Directory.CreateDirectory(outputDir);
320→
321→    var results = new List<PackResult>();
322→    
323→    // Build and pack sequentially to avoid file lock issues with dependencies
324→    foreach (var project in projects)
325→    {
326→        var projectName = Path.GetFileNameWithoutExtension(project);
327→        
328→        try
329→        {
330→            // Build with output capture
331→            var buildOutput = new StringBuilder();
332→            var buildError = new StringBuilder();
333→            
334→            var buildResult = await Cli.Wrap("dotnet")
335→                .WithArguments($"build \"{project}\" -c {config} --verbosity normal")
336→                .WithValidation(CommandResultValidation.None)
337→                .WithStandardOutputPipe(PipeTarget.ToStringBuilder(buildOutput))
338→                .WithStandardErrorPipe(PipeTarget.ToStringBuilder(buildError))
339→                .ExecuteAsync();
340→
341→            if (buildResult.ExitCode != 0)
342→            {
343→                var errorMessage = GetErrorMessage(buildError.ToString(), buildOutput.ToString(), "Build failed");
344→                results.Add(new PackResult(projectName, false, errorMessage));
345→                continue;
346→            }
347→
348→            // Pack — symbols are controlled via Directory.Build.props (IncludeSymbols=true)
349→            // and overridden for native packages via Directory.NativePackage.props (IncludeSymbols=false).
350→            // The --no-symbols flag forces symbols off for all projects via -p: override.
351→            var packOutput = new StringBuilder();
352→            var packError = new StringBuilder();
353→
354→            var packArgs = includeSymbols
355→                ? $"pack \"{project}\" -c {config} -o \"{outputDir}\" --no-build --verbosity normal"
356→                : $"pack \"{project}\" -c {config} -o \"{outputDir}\" --no-build -p:IncludeSymbols=false --verbosity normal";
357→            
358→            var packResult = await Cli.Wrap("dotnet")
359→                .WithArguments(packArgs)
360→                .WithValidation(CommandResultValidation.None)
361→                .WithStandardOutputPipe(PipeTarget.ToStringBuilder(packOutput))
362→                .WithStandardErrorPipe(PipeTarget.ToStringBuilder(packError))
363→                .ExecuteAsync();
364→
365→            if (packResult.ExitCode != 0)
366→            {
367→                var errorMessage = GetErrorMessage(packError.ToString(), packOutput.ToString(), "Pack failed");
368→                results.Add(new PackResult(projectName, false, errorMessage));
369→                continue;
370→            }
371→
372→            results.Add(new PackResult(projectName, true, "Success"));
373→        }
374→        catch (Exception ex)
375→        {
376→            results.Add(new PackResult(projectName, false, ex.Message));
377→        }
378→    }
379→
380→    return results;
381→}
