384→Task<List<PublishResult>> CopyPackagesToLocalFeedAsync(List<PackResult> packResults, string localFeedPath, string outputDir)
385→{
386→    var successfulPacks = packResults.Where(r => r.Success).ToList();
387→    
388→    // Ensure local feed directory exists
389→    Directory.CreateDirectory(localFeedPath);
390→    
391→    var results = new List<PublishResult>();
392→    
393→    foreach (var pack in successfulPacks)
394→    {
395→        try
396→        {
397→            // Find .nupkg files for this project (exact match to avoid prefix collisions)
398→            var packageFiles = Directory.GetFiles(outputDir, "*.nupkg")
399→                .Where(f => !f.EndsWith(".snupkg"))
400→                .Where(f => IsExactPackageFile(f, pack.ProjectName))
401→                .OrderByDescending(f => File.GetLastWriteTime(f))
402→                .ToArray();
403→
404→            if (packageFiles.Length == 0)
405→            {
406→                results.Add(new PublishResult(pack.ProjectName, false, "No .nupkg files found"));
407→                continue;
408→            }
409→
410→            var latestNugetPackage = packageFiles[0];
411→            var packageBaseName = Path.GetFileNameWithoutExtension(latestNugetPackage);
412→
413→            // Find corresponding .snupkg files (exact match)
414→            var snupkgFiles = Directory.GetFiles(outputDir, "*.snupkg")
415→                .Where(f => IsExactPackageFile(f, pack.ProjectName))
416→                .Where(f => Path.GetFileNameWithoutExtension(f) == packageBaseName)
417→                .OrderByDescending(f => File.GetLastWriteTime(f))
418→                .ToArray();
419→
420→            // Copy main package file
421→            var mainFileName = Path.GetFileName(latestNugetPackage);
422→            var mainDestPath = Path.Combine(localFeedPath, mainFileName);
423→            File.Copy(latestNugetPackage, mainDestPath, true);
424→            
425→            var copiedFiles = 1;
426→            
427→            // Copy symbols package if it exists
428→            if (snupkgFiles.Length > 0)
429→            {
430→                var latestSnupkgFile = snupkgFiles[0];
431→                var symbolFileName = Path.GetFileName(latestSnupkgFile);
432→                var symbolDestPath = Path.Combine(localFeedPath, symbolFileName);
433→                File.Copy(latestSnupkgFile, symbolDestPath, true);
434→                copiedFiles++;
435→            }
436→
437→            var message = copiedFiles == 1 
438→                ? $"Copied package to {localFeedPath}" 
439→                : $"Copied package and symbols to {localFeedPath}";
440→                
441→            results.Add(new PublishResult(pack.ProjectName, true, message));
442→        }
443→        catch (Exception ex)
444→        {
445→            results.Add(new PublishResult(pack.ProjectName, false, ex.Message));
446→        }
447→    }
448→    
449→    return Task.FromResult(results);
450→}
451→
452→async Task<List<PublishResult>> PublishPackagesAsync(
453→  List<PackResult> packResults, 
454→  PublishMode mode, 
455→  string feedUrl, 
456→  string apiKey,
457→  string outputDir)
458→{
459→    var successfulPacks = packResults.Where(r => r.Success).ToList();
460→
461→    var tasks = successfulPacks.Select(async pack =>
462→    {
463→        try
464→        {
465→            // Find the latest .nupkg file for this project (exact match to avoid prefix collisions)
466→            var packageFiles = Directory.GetFiles(outputDir, "*.nupkg")
467→                .Where(f => !f.EndsWith(".snupkg"))
468→                .Where(f => IsExactPackageFile(f, pack.ProjectName))
469→                .OrderByDescending(f => File.GetLastWriteTime(f))
470→                .ToArray();
471→
472→            if (packageFiles.Length == 0)
473→            {
474→                return new PublishResult(pack.ProjectName, false, "No package file found");
475→            }
476→
477→            var latestNugetPackage = packageFiles[0];
478→
479→            // Find corresponding .snupkg file (exact match)
480→            var packageBaseName = Path.GetFileNameWithoutExtension(latestNugetPackage);
481→            var snupkgFiles = Directory.GetFiles(outputDir, "*.snupkg")
482→                .Where(f => IsExactPackageFile(f, pack.ProjectName))
483→                .Where(f => Path.GetFileNameWithoutExtension(f) == packageBaseName)
484→                .OrderByDescending(f => File.GetLastWriteTime(f))
485→                .ToArray();
486→
487→            // Push main package
488→            var pushOutput = new StringBuilder();
489→            var pushError = new StringBuilder();
490→            
491→            var pushResult = await Cli.Wrap("dotnet")
492→                .WithArguments($"nuget push \"{latestNugetPackage}\" --skip-duplicate --api-key \"{apiKey}\" --source \"{feedUrl}\"")
493→                .WithValidation(CommandResultValidation.None)
494→                .WithStandardOutputPipe(PipeTarget.ToStringBuilder(pushOutput))
495→                .WithStandardErrorPipe(PipeTarget.ToStringBuilder(pushError))
496→                .ExecuteAsync();
497→
498→            if (pushResult.ExitCode != 0)
499→            {
500→                var errorMessage = GetErrorMessage(pushError.ToString(), pushOutput.ToString(), "Push failed");
501→                return new PublishResult(pack.ProjectName, false, errorMessage);
502→            }
503→
504→            // Push symbols if exists (matching the PowerShell script logic)
505→            if (snupkgFiles.Length > 0)
506→            {
507→                var latestSnupkgFile = snupkgFiles[0];
508→                var symbolPushOutput = new StringBuilder();
509→                var symbolPushError = new StringBuilder();
510→                
511→                var symbolPushResult = await Cli.Wrap("dotnet")
512→                    .WithArguments($"nuget push \"{latestSnupkgFile}\" --skip-duplicate --api-key \"{apiKey}\" --source \"{feedUrl}\"")
513→                    .WithValidation(CommandResultValidation.None)
514→                    .WithStandardOutputPipe(PipeTarget.ToStringBuilder(symbolPushOutput))
515→                    .WithStandardErrorPipe(PipeTarget.ToStringBuilder(symbolPushError))
516→                    .ExecuteAsync();
517→
518→                // Symbol push failure is not critical
519→                if (symbolPushResult.ExitCode != 0)
520→                {
521→                    return new PublishResult(pack.ProjectName, true, "Package published (symbols failed)");
522→                }
523→                
524→                return new PublishResult(pack.ProjectName, true, "Published with symbols");
525→            }
526→
527→            return new PublishResult(pack.ProjectName, true, "Published successfully");
528→        }
529→        catch (Exception ex)
530→        {
531→            return new PublishResult(pack.ProjectName, false, ex.Message);
532→        }
533→    });
534→
535→    return (await Task.WhenAll(tasks)).ToList();
536→}
