538→void ReportPackedProjects(List<PackResult> results)
539→{
540→    AnsiConsole.WriteLine();
541→    AnsiConsole.Write(new Rule("[green]📦 Packaging Results[/]").LeftJustified());
542→    
543→    var table = new Table()
544→        .Border(TableBorder.Rounded)
545→        .AddColumn("Project")
546→        .AddColumn("Status")
547→        .AddColumn(new TableColumn("Details").Width(60));
