659→string GetErrorMessage(string stderr, string stdout, string defaultMessage)
660→{
661→    // Combine stderr and stdout
662→    var allOutput = $"{stderr}\n{stdout}".Trim();
663→    
664→    if (string.IsNullOrWhiteSpace(allOutput))
665→        return defaultMessage;
666→    
667→    // Look for error lines
668→    var lines = allOutput.Split('\n', StringSplitOptions.RemoveEmptyEntries);
669→    var errorLines = lines.Where(line => 
670→        line.Contains("error", StringComparison.OrdinalIgnoreCase) ||
671→        line.Contains("failed", StringComparison.OrdinalIgnoreCase) ||
672→        line.Contains("exception", StringComparison.OrdinalIgnoreCase))
673→        .Take(3) // Limit to first 3 error lines
674→        .ToArray();
675→    
676→    if (errorLines.Length > 0)
677→    {
678→        // Clean up the error messages
679→        var cleanErrors = errorLines.Select(line => 
680→            line.Trim()
681→                .Replace("error:", "", StringComparison.OrdinalIgnoreCase)
682→                .Replace("Error:", "", StringComparison.OrdinalIgnoreCase)
683→                .Trim())
684→            .Where(line => !string.IsNullOrWhiteSpace(line))
685→            .ToArray();
686→        
687→        if (cleanErrors.Length > 0)
688→        {
689→            return string.Join(" | ", cleanErrors);
690→        }
691→    }
692→    
693→    // If no specific errors found, return first few lines of output
694→    var firstLines = lines.Take(2).Where(line => !string.IsNullOrWhiteSpace(line)).ToArray();
695→    return firstLines.Length > 0 ? string.Join(" | ", firstLines) : defaultMessage;
696→}
