708→// Matches package files by exact project name (avoids prefix collisions like
709→// "WebView" matching "WebView.Desktop"). The filename after the project name
710→// must be ".{digit}" (the start of a version number).
711→bool IsExactPackageFile(string filePath, string projectName)
712→{
713→    var fileName = Path.GetFileName(filePath);
714→    var prefix = projectName + ".";
715→    return fileName.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)
716→        && fileName.Length > prefix.Length
717→        && char.IsDigit(fileName[prefix.Length]);
718→}
