184→static int RunProcess(string fileName, string arguments, string workingDirectory, bool verbose)
185→{
186→    Console.WriteLine($"> {fileName} {arguments}");
187→
188→    var startInfo = new ProcessStartInfo
189→    {
190→        FileName = fileName,
191→        Arguments = arguments,
192→        WorkingDirectory = workingDirectory,
193→        RedirectStandardOutput = verbose,
194→        RedirectStandardError = verbose,
195→        UseShellExecute = !verbose
196→    };
197→
198→    try
199→    {
200→        using var process = Process.Start(startInfo);
201→        if (process == null)
202→        {
203→            Console.Error.WriteLine($"Failed to start process: {fileName}");
204→            return 1;
205→        }
206→
207→        if (verbose)
208→        {
209→            process.OutputDataReceived += (_, e) =>
210→            {
211→                if (!string.IsNullOrEmpty(e.Data))
212→                {
213→                    Console.WriteLine(e.Data);
214→                }
215→            };
216→            process.ErrorDataReceived += (_, e) =>
217→            {
218→                if (!string.IsNullOrEmpty(e.Data))
219→                {
220→                    Console.Error.WriteLine(e.Data);
221→                }
222→            };
223→            process.BeginOutputReadLine();
224→            process.BeginErrorReadLine();
225→        }
226→
227→        process.WaitForExit();
228→        return process.ExitCode;
229→    }
230→    catch (Exception ex)
