271→sealed class BuildOptions
272→{
273→    public string? Project { get; set; }
274→    public string OutputDirectory { get; set; } = string.Empty;
275→    public string Configuration { get; set; } = "Release";
276→    public bool Force { get; set; }
277→    public bool Verbose { get; set; }
278→
279→    public static BuildOptions Parse(string[] arguments)
280→    {
281→        var options = new BuildOptions();
282→
283→        for (var i = 0; i < arguments.Length; i++)
284→        {
285→            var arg = arguments[i];
286→
287→            switch (arg)
288→            {
289→                case "--project":
290→                    options.Project = GetValue(arguments, ref i);
291→                    break;
292→                case "--out-dir":
293→                    options.OutputDirectory = Path.GetFullPath(GetValue(arguments, ref i));
294→                    break;
295→                case "--configuration":
296→                    options.Configuration = GetValue(arguments, ref i);
297→                    break;
298→                case "--force":
299→                case "-f":
300→                    options.Force = true;
301→                    break;
302→                case "--verbose":
303→                case "-v":
304→                    options.Verbose = true;
305→                    break;
306→                default:
307→                    Console.WriteLine($"Unknown argument ignored: {arg}");
308→                    break;
309→            }
310→        }
311→
312→        return options;
313→    }
314→
315→    private static string GetValue(string[] args, ref int index)
316→    {
317→        if (index + 1 >= args.Length)
318→        {
319→            throw new ArgumentException($"Missing value for {args[index]}");
320→        }
321→
322→        index++;
323→        return args[index];
324→    }
325→}
