362→static class ChecksumCollector
363→{
364→    public static Dictionary<string, string> Collect(string projectDir)
365→    {
366→        var checksums = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
367→
368→        var nativeDir = Path.Combine(projectDir, "native");
369→        var codegenDir = Path.Combine(projectDir, "codegen");
370→
371→        AddFile(checksums, Path.Combine(nativeDir, "Cargo.toml"), Path.Combine("native", "Cargo.toml"));
372→        AddFile(checksums, Path.Combine(codegenDir, "Cargo.toml"), Path.Combine("codegen", "Cargo.toml"));
373→
374→        AddDirectory(checksums, Path.Combine(nativeDir, "src"), "native/src");
375→        AddDirectory(checksums, Path.Combine(codegenDir, "src"), "codegen/src");
376→
377→        return checksums;
378→    }
379→
380→    public static bool HasDifferences(
381→        Dictionary<string, string> previous,
382→        Dictionary<string, string> current,
383→        string prefix)
384→    {
385→        foreach (var kvp in current)
386→        {
387→            if (!kvp.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
388→            {
389→                continue;
390→            }
391→
392→            if (!previous.TryGetValue(kvp.Key, out var oldChecksum) || !oldChecksum.Equals(kvp.Value, StringComparison.OrdinalIgnoreCase))
393→            {
394→                return true;
395→            }
396→        }
397→
398→        foreach (var kvp in previous)
399→        {
400→            if (!kvp.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
401→            {
402→                continue;
403→            }
404→
405→            if (!current.ContainsKey(kvp.Key))
406→            {
407→                return true;
408→            }
409→        }
410→
411→        return false;
412→    }
413→
414→    private static void AddDirectory(Dictionary<string, string> checksums, string directory, string prefix)
415→    {
416→        if (!Directory.Exists(directory))
417→        {
418→            return;
419→        }
420→
