        {(publishResults.Count > 0 ? $"[green]Published Projects:[/] {publishResults.Count(r => r.Success)}/{publishResults.Count}" : "")}
        {(publishResults.Count > 0 && !string.IsNullOrEmpty(publishedTo) ? $"[green]Published To:[/] {publishedTo}" : "")}
